window.MR_LOCAL_STORIES = [{"id":"1-3-01-dlinnaya","topicId":"1-3-01","slug":"karmanchik-kotoryy-zhdal-dlinnaya","age":"1–3 года","ageKey":"1-3","theme":"Первое расставание с мамой","version":"Длинная","duration":"10–15 минут","title":"Карманчик, который ждал","hero":"зайчонок Тишка","teaser":"Зайчонок Тишка впервые остаётся играть без мамы и замечает, что разлука может быть короткой, а мама действительно возвращается.","text":"У зайчонка Тишки был маленький синий рюкзачок. В рюкзачке — запасные носочки, яблоко и машинка с одним красным колесом.\n\nА ещё у Тишки был карманчик.\n\nСамый обычный карманчик на кофточке. Но сегодня мама положила туда маленький круглый платочек с жёлтым солнышком.\n\n— Это не волшебство, — сказала мама. — Просто кусочек дома.\n\nТишка потрогал карманчик лапкой.\n\nШур-шур.\n\nСегодня он впервые пришёл в Домик маленьких шагов. Там были низкие столики, мягкие кубики, деревянный поезд и окно почти до самого пола.\n\nУ двери мама присела рядом.\n\n— Я сейчас уйду по своим делам. Ты останешься с тётей Белкой и ребятами. А потом я вернусь.\n\nТишка сразу обнял мамину шею.\n\nКрепко-крепко.\n\n— Мама тут.\n\n— Сейчас я тут, — сказала мама и погладила его по спинке. — А потом уйду. Ты можешь грустить. Я всё равно вернусь.\n\nТишка посмотрел на дверь.\n\nДверь ему не понравилась.\n\nОна умела закрываться.\n\nМама поцеловала Тишку, помахала ему рукой и вышла.\n\nЩёлк.\n\nДверь закрылась.\n\nТишка замер.\n\nПотом губы у него задрожали.\n\n— Ма-а-ма!\n\nТётя Белка не стала говорить: «Не плачь».\n\nОна села рядом на ковёр.\n\n— Ты скучаешь.\n\nТишка кивнул и заплакал.\n\nКап-кап-кап.\n\nОн сунул лапку в карман.\n\nШур-шур.\n\nПальчики нашли платочек с солнышком.\n\nТишка прижал его к щеке.\n\nПахло домом. Совсем чуть-чуть. Маминым кремом и чистым бельём.\n\nНа другом конце комнаты кто-то сказал:\n\n— Ту-ту!\n\nПо рельсам ехал деревянный поезд. Его толкал маленький барсучок.\n\n— Ту-ту! Ту-ту!\n\nТишка посмотрел.\n\nПлакать хотелось всё ещё.\n\nНо поезд ехал смешно. Один вагон всё время отцеплялся.\n\n— Бух! — падал вагон.\n\nБарсучок снова ставил его на рельсы.\n\n— Ту-ту!\n\nТишка подошёл на один шаг.\n\nПотом ещё на один.\n\nПлаточек он держал в лапке.\n\nБарсучок протянул ему зелёный вагон.\n\nТишка не взял.\n\nБарсучок положил вагон рядом.\n\nТишка сел.\n\nМинутку они просто сидели.\n\nПотом Тишка подтолкнул вагон.\n\nТук.\n\nБарсучок прицепил его к поезду.\n\n— Ту-ту!\n\nТишка тоже тихо сказал:\n\n— Ту.\n\nПоезд поехал вокруг кубика, под стулом и прямо к тёте Белке.\n\n— Ой! Станция! — сказала она.\n\nТишка улыбнулся.\n\nСовсем немножко.\n\nПотом ребята ели кусочки груши.\n\nТишка вспомнил маму и снова нахмурился.\n\nЛапка — в карман.\n\nШур-шур.\n\nСолнышко на месте.\n\nПосле груши все пошли к окну. За стеклом прыгал воробей.\n\nПрыг-прыг.\n\nКлюв-клюв.\n\nТишка показал на него пальчиком.\n\n— Пти!\n\n— Птичка, — сказала тётя Белка.\n\nПотом они строили башню.\n\nОдин кубик.\n\nДва кубика.\n\nТри.\n\nБух!\n\nБашня упала.\n\nТишка засмеялся.\n\nИ тут за дверью послышались шаги.\n\nТоп.\n\nТоп.\n\nТоп.\n\nЩёлк.\n\nДверь открылась.\n\nНа пороге стояла мама.\n\nТишка секунду смотрел, будто проверял: правда?\n\nА потом побежал.\n\nТоп-топ-топ-топ!\n\n— Мама!\n\nМама подхватила его.\n\n— Я пришла.\n\nТишка обнял её, потом быстро показал деревянный поезд, барсучка, окно и даже кубики.\n\nСлов было мало, поэтому он показывал руками:\n\n— Ту-ту! Бух! Пти!\n\nМама всё поняла.\n\nУ двери Тишка вдруг вспомнил про платочек.\n\nОн достал его из кармашка.\n\nЖёлтое солнышко чуть-чуть помялось.\n\nТишка погладил его пальчиком и положил обратно.\n\nШур-шур.\n\nКарманчик снова был закрыт.\n\nНо теперь Тишка знал, что за закрытой дверью может быть игра.\n\nА потом снова бывают шаги.\n\nТоп.\n\nТоп.\n\nТоп.\n\nИ дверь открывается.","question":"А что могло бы лежать в твоём кармашке и напоминать тебе о доме?","image":"assets/images/stories/karmanchik-kotoryy-zhdal-dlinnaya.webp","audio":"","published":true},{"id":"1-3-01-korotkaya","topicId":"1-3-01","slug":"karmanchik-kotoryy-zhdal-korotkaya","age":"1–3 года","ageKey":"1-3","theme":"Первое расставание с мамой","version":"Короткая","duration":"3–5 минут","title":"Карманчик, который ждал","hero":"зайчонок Тишка","teaser":"Зайчонок Тишка впервые остаётся играть без мамы и замечает, что разлука может быть короткой, а мама действительно возвращается.","text":"У зайчонка Тишки был маленький карманчик на кофточке.\n\nСегодня мама положила туда платочек с жёлтым солнышком.\n\n— Это кусочек дома, — сказала она.\n\nТишка впервые пришёл в Домик маленьких шагов. Там были кубики, деревянный поезд и много ребят.\n\nУ двери мама присела рядом.\n\n— Я сейчас уйду, а потом вернусь.\n\nТишка крепко обнял маму.\n\nМама поцеловала его и вышла.\n\nЩёлк.\n\nДверь закрылась.\n\n— Ма-а-ма! — заплакал Тишка.\n\nТётя Белка села рядом.\n\n— Ты скучаешь.\n\nТишка сунул лапку в карман.\n\nШур-шур.\n\nТам было маленькое солнышко. Платочек пах домом.\n\nВдруг по комнате поехал поезд.\n\n— Ту-ту!\n\nЕго толкал барсучок. Один вагон всё время падал.\n\n— Бух!\n\nТишка посмотрел.\n\nПотом подошёл поближе.\n\nБарсучок положил рядом зелёный вагон.\n\nТишка подтолкнул его.\n\nТук.\n\n— Ту-ту! — сказал барсучок.\n\n— Ту, — ответил Тишка.\n\nПотом ребята ели грушу, смотрели на воробья и строили башню.\n\nБашня упала:\n\n— Бух!\n\nТишка засмеялся.\n\nИ тут послышались шаги.\n\nТоп.\n\nТоп.\n\nТоп.\n\nЩёлк.\n\nДверь открылась.\n\nНа пороге стояла мама.\n\n— Мама!\n\nТишка побежал к ней.\n\nМама подхватила его на руки.\n\n— Я пришла.\n\nТишка показал ей поезд, кубики и воробья за окном.\n\nА потом потрогал свой карманчик.\n\nШур-шур.\n\nСолнышко всё это время было с ним.\n\nА мама вернулась.","question":"А что могло бы лежать в твоём кармашке и напоминать тебе о доме?","image":"assets/images/stories/karmanchik-kotoryy-zhdal-korotkaya.webp","audio":"","published":true},{"id":"1-3-02-dlinnaya","topicId":"1-3-02","slug":"kto-shurshit-v-tyomnoy-komnate-dlinnaya","age":"1–3 года","ageKey":"1-3","theme":"Боязнь темноты","version":"Длинная","duration":"10–15 минут","title":"Кто шуршит в тёмной комнате?","hero":"енотик Буся","teaser":"Енотик Буся вместе с маленьким фонариком узнаёт, во что превращаются знакомые вещи, когда в комнате гаснет свет.","text":"Енотик Буся любил свою комнату днём.\n\nДнём у окна стояло кресло.\n\nНа кресле лежал плед.\n\nНа полке сидел медведь.\n\nА на крючке висела полосатая кофточка.\n\nВсё было знакомое.\n\nНо вечером мама сказала:\n\n— Пора выключать большой свет.\n\nЩёлк.\n\nКомната стала тёмной.\n\nИ сразу возле кресла появилось что-то огромное.\n\nБуся спрятал нос под одеяло.\n\n— Там кто-то!\n\nМама села на край кровати.\n\n— Давай посмотрим.\n\nОна включила маленький ночник.\n\nТёплый круг света лёг на пол.\n\nОгромное что-то стало креслом.\n\nА сверху на нём лежал плед.\n\n— Кресло, — сказал Буся.\n\nМама снова выключила свет.\n\nЩёлк.\n\nВ углу что-то длинное качнулось.\n\nШ-ш-ш.\n\nБуся снова спрятался.\n\n— Там шуршит!\n\nМама не смеялась.\n\n— Слышишь? Ш-ш-ш. Давай найдём.\n\nУ Буси был маленький фонарик. Красный. С круглой кнопкой.\n\nБуся высунул одну лапку.\n\nНажал.\n\nКлик.\n\nНа стене появился светлый кружок.\n\nБуся повёл фонариком по комнате.\n\nПо подушке.\n\nПо полу.\n\nПо шкафу.\n\nКружок добрался до угла.\n\nТам висела полосатая кофточка.\n\nРукав качался от ветерка.\n\nШ-ш-ш.\n\n— Кофта, — сказал Буся.\n\nОн потрогал рукав.\n\nМягкий.\n\nСовсем не страшный.\n\nПотом на потолке вдруг появилась большая лапа.\n\nБуся замер.\n\nЛапа тоже замерла.\n\nБуся пошевелил пальчиками.\n\nЛапа на потолке пошевелилась.\n\nБуся поднял фонарик.\n\n— Это я!\n\nОн сложил лапки вместе.\n\nНа стене появился смешной зверь с ушами.\n\nБуся сделал ушки длиннее.\n\nЗверь стал похож на зайца.\n\n— Прыг-прыг, — сказал Буся.\n\nМама улыбнулась.\n\nПотом они выключили фонарик.\n\nВ комнате снова стало темно.\n\nБуся уже хотел лечь, но тут за шторой:\n\nТук.\n\nТук.\n\nТук.\n\nБуся приподнялся.\n\n— Что там?\n\nОни подошли к окну.\n\nЗа стеклом веточка сирени тихонько касалась окна.\n\nТук.\n\nТук.\n\nТук.\n\n— Ветка, — сказал Буся.\n\nМама закрыла штору плотнее.\n\nТук стало совсем тихим.\n\nБуся вернулся в кровать.\n\nТеперь он сам попросил:\n\n— Свет — щёлк.\n\nМама выключила ночник.\n\nЩёлк.\n\nКомната стала тёмной.\n\nКресло превратилось в большую круглую тень.\n\nКофточка — в длинную.\n\nМедведь на полке почти исчез.\n\nБуся смотрел.\n\nТени никуда не шли.\n\nОни просто были рядом с вещами.\n\nБуся включил фонарик ещё раз.\n\nКлик.\n\nСветлый кружок прыгнул на стену.\n\n— Медведь.\n\nКлик.\n\n— Кресло.\n\nКлик.\n\n— Кофта.\n\nКлик.\n\n— Буся.\n\nОн посветил на свои лапы и засмеялся.\n\nПотом мама положила фонарик возле кровати.\n\n— Он будет здесь.\n\nБуся забрался под одеяло.\n\nИз окна на стену легла тонкая полоска лунного света.\n\nНа потолке появилась маленькая светлая точка.\n\nПотом ещё одна.\n\nЭто отражались звёздочки с наклейки на шкафу.\n\nБуся посчитал:\n\n— Одна. Две. Ти.\n\nОн зевнул.\n\nШ-ш-ш.\n\nКофточка чуть качнулась.\n\n— Кофта, — сонно сказал Буся.\n\nТук.\n\nВетка коснулась окна.\n\n— Ветка.\n\nНа стене лежала тень кресла.\n\n— Кресло.\n\nБуся закрыл глаза.\n\nКомната была всё той же комнатой.\n\nПросто ночью у знакомых вещей появлялись тени.","question":"На что может быть похожа тень в твоей комнате?","image":"assets/images/stories/kto-shurshit-v-tyomnoy-komnate-dlinnaya.webp","audio":"","published":true},{"id":"1-3-02-korotkaya","topicId":"1-3-02","slug":"kto-shurshit-v-tyomnoy-komnate-korotkaya","age":"1–3 года","ageKey":"1-3","theme":"Боязнь темноты","version":"Короткая","duration":"3–5 минут","title":"Кто шуршит в тёмной комнате?","hero":"енотик Буся","teaser":"Енотик Буся вместе с маленьким фонариком узнаёт, во что превращаются знакомые вещи, когда в комнате гаснет свет.","text":"Днём енотик Буся любил свою комнату.\n\nВот кресло.\n\nВот плед.\n\nВот медведь.\n\nВот полосатая кофточка.\n\nА вечером мама выключила большой свет.\n\nЩёлк.\n\nВозле кресла появилась огромная тень.\n\nБуся спрятал нос под одеяло.\n\n— Там кто-то!\n\nМама включила маленький фонарик.\n\nКлик.\n\nСвет упал на тень.\n\nЭто было кресло с пледом.\n\n— Кресло, — сказал Буся.\n\nВ углу что-то зашуршало:\n\n— Ш-ш-ш.\n\nБуся посветил туда.\n\nНа крючке висела кофточка. Её рукав качал ветер.\n\n— Кофта.\n\nПотом на стене появилась большая лапа.\n\nБуся пошевелил своей лапкой.\n\nТень тоже пошевелилась.\n\n— Это я!\n\nБуся сделал пальчиками ушки.\n\nНа стене появился зайчик.\n\n— Прыг-прыг!\n\nВдруг у окна:\n\n— Тук. Тук.\n\nЭто веточка касалась стекла.\n\n— Ветка, — сказал Буся.\n\nОн снова лёг в кровать.\n\nМама выключила свет.\n\nЩёлк.\n\nТени вернулись.\n\nБуся посмотрел на них.\n\nБольшая тень — кресло.\n\nДлинная — кофточка.\n\nТук — веточка.\n\nШ-ш-ш — ветер.\n\nБуся положил фонарик рядом.\n\nНа потолке блеснули маленькие звёздочки.\n\n— Одна. Две. Ти…\n\nОн зевнул и закрыл глаза.\n\nНочью комната оставалась той же комнатой.\n\nПросто у знакомых вещей появлялись тени.","question":"На что может быть похожа тень в твоей комнате?","image":"assets/images/stories/kto-shurshit-v-tyomnoy-komnate-korotkaya.webp","audio":"","published":true},{"id":"1-3-03-dlinnaya","topicId":"1-3-03","slug":"posledniy-krug-parovozika-chufa-dlinnaya","age":"1–3 года","ageKey":"1-3","theme":"Не хочу спать","version":"Длинная","duration":"10–15 минут","title":"Последний круг паровозика Чуфа","hero":"маленький паровозик Чуф","teaser":"Маленький паровозик Чуф совсем не хочет заканчивать день, пока его собственные колёса не подсказывают, что пора в тёплое депо.","text":"Маленький паровозик Чуф весь день ездил по своей железной дороге.\n\nТу-ту!\n\nУтром он вёз кубики.\n\nДнём — три жёлтых мяча.\n\nПосле полдника — плюшевого слона.\n\nА вечером Чуф возил пустой вагон просто так.\n\nПотому что было весело.\n\nТу-ту!\n\nЗа окном станции стало темнеть.\n\nБольшой поезд Брум заехал в депо.\n\n— Спокойной ночи!\n\nТрамвайчик Дзинь встал под навес.\n\n— Дзинь-дзинь. До утра!\n\nДаже маленькая дрезина спряталась в свой гараж.\n\nА Чуф ездил.\n\nТу-ту!\n\nСмотритель станции сказал:\n\n— Чуф, рельсы скоро будут отдыхать.\n\n— Не-а! — прогудел Чуф. — Ещё круг!\n\nОн поехал вокруг башни.\n\nЧух-чух-чух.\n\nМимо мостика.\n\nЧух-чух.\n\nМимо фонаря.\n\nЧух…\n\nНа подъёме колёса вдруг поехали медленнее.\n\n— Ещё круг! — сказал Чуф.\n\nОн спустился с горки.\n\nУ-у-ух!\n\nСтало весело.\n\nСон как будто убежал.\n\nЧуф снова оживился.\n\n— Видите? Я не хочу спать!\n\nОн проехал мимо депо.\n\nВнутри было тепло. По стене шёл мягкий жёлтый свет.\n\nНо Чуф отвернулся.\n\n— Ещё один круг.\n\nОн решил отвезти в дальний угол станции один синий кубик.\n\nКубик положили в вагон.\n\nЧуф тронулся.\n\nЧух-чух.\n\nНа первом повороте вагон тихонько качнулся.\n\nНа втором Чуф зевнул:\n\n— Ту-у-у…\n\nГудок получился длинный и сонный.\n\n— Это не зевок, — сказал Чуф. — Это гудок.\n\nОн доехал до дальнего угла.\n\nПотом вдруг забыл, зачем приехал.\n\nПосмотрел на кубик.\n\nПосмотрел на рельсы.\n\n— Э-э…\n\nСмотритель станции подошёл поближе.\n\n— Кажется, твои колёса устали.\n\nЧуф прислушался.\n\nОбычно они говорили:\n\nЧух-чух! Чух-чух!\n\nА теперь:\n\nЧух… чух…\n\nЧуф покрутил колёсами.\n\nОни не болели.\n\nПросто двигались медленно.\n\n— Я ещё хочу играть, — сказал он.\n\n— Можно хотеть играть и всё равно устать, — ответил смотритель.\n\nЧуф подумал.\n\nЕму не нравилось слово «всё».\n\n«Всё, игра закончилась».\n\n«Всё, пора спать».\n\nСлишком быстро.\n\nТогда Чуф придумал:\n\n— Я сделаю последний круг. Но специальный.\n\n— Какой?\n\n— Сонный.\n\nНа сонном круге нельзя было спешить.\n\nСначала Чуф проехал мимо мостика.\n\n— Мостику — спокойной ночи.\n\nПотом мимо башни.\n\n— Башне — спокойной ночи.\n\nПотом мимо фонаря.\n\n— Фонарю — спокойной ночи.\n\nФонарь мигнул:\n\nМиг.\n\nЧуф проехал мимо трёх вагончиков.\n\n— Красному — спокойной ночи. Зелёному — спокойной ночи. Синему — спокойной ночи.\n\nПотом он подъехал к депо.\n\nУ ворот остановился.\n\nКолёса ещё чуть-чуть крутились.\n\n— Стоп, — сказал Чуф.\n\nКолёса остановились.\n\nСмотритель протёр ему фары мягкой салфеткой.\n\nПроверил колёса.\n\nПоставил рядом маленькую кружку воды для паровозиков.\n\nЧуф устроился на своём месте.\n\n— А утром рельсы будут?\n\n— Будут.\n\n— И мостик?\n\n— Будет.\n\n— И синий кубик?\n\nСмотритель посмотрел на вагон.\n\nКубик всё ещё лежал там.\n\n— И кубик будет.\n\nЧуф успокоился.\n\nНичего не исчезало только потому, что наступала ночь.\n\nОн закрыл фары.\n\nВ депо стало тихо.\n\nКап.\n\nГде-то остывала труба.\n\nШ-ш-ш.\n\nЗа воротами шёл ветер.\n\nЧуф вдруг вспомнил:\n\n— Я же кубик вёз!\n\nОн хотел открыть глаза.\n\nНо не открыл.\n\n— Завтра довезу, — пробормотал он.\n\nИ тихо сказал самый последний гудок:\n\n— Ту-у…\n\nА утром первым делом солнечный луч заглянул в депо.\n\nЧуф открыл фары.\n\nРельсы были на месте.\n\nМостик был на месте.\n\nИ синий кубик тоже.\n\n— Ту-ту! — радостно сказал Чуф.\n\nНовый день начался.","question":"Что тебе нравится делать самым последним перед сном?","image":"assets/images/stories/posledniy-krug-parovozika-chufa-dlinnaya.webp","audio":"","published":true},{"id":"1-3-03-korotkaya","topicId":"1-3-03","slug":"posledniy-krug-parovozika-chufa-korotkaya","age":"1–3 года","ageKey":"1-3","theme":"Не хочу спать","version":"Короткая","duration":"3–5 минут","title":"Последний круг паровозика Чуфа","hero":"маленький паровозик Чуф","teaser":"Маленький паровозик Чуф совсем не хочет заканчивать день, пока его собственные колёса не подсказывают, что пора в тёплое депо.","text":"Маленький паровозик Чуф весь день ездил по рельсам.\n\nТу-ту!\n\nВечером большой поезд уехал в депо.\n\nТрамвайчик спрятался под навес.\n\nДаже дрезина пошла отдыхать.\n\nА Чуф сказал:\n\n— Не хочу спать! Ещё круг!\n\nОн поехал вокруг башни.\n\nЧух-чух-чух.\n\nМимо мостика.\n\nЧух-чух.\n\nМимо фонаря.\n\nЧух…\n\nКолёса стали ехать медленнее.\n\n— Я не устал! — сказал Чуф.\n\nОн повёз синий кубик.\n\nНа первом повороте Чуф зевнул:\n\n— Ту-у-у…\n\n— Это гудок, — сказал он.\n\nНо колёса уже шептали:\n\nЧух… чух…\n\nТогда Чуф придумал последний круг.\n\nСонный.\n\nОн поехал медленно.\n\n— Мостику — спокойной ночи.\n\n— Башне — спокойной ночи.\n\n— Фонарю — спокойной ночи.\n\nФонарь мигнул:\n\nМиг.\n\nЧуф подъехал к депо.\n\n— Колёса, стоп.\n\nКолёса остановились.\n\nЧуф устроился на своём месте.\n\n— А утром рельсы будут?\n\n— Будут.\n\n— И мостик?\n\n— Будет.\n\n— И мой кубик?\n\n— Конечно.\n\nЧуф закрыл фары.\n\n— Завтра доиграю, — сонно сказал он.\n\n— Ту-у…\n\nА утром всё было на месте.\n\nИ рельсы.\n\nИ мостик.\n\nИ синий кубик.\n\n— Ту-ту! — сказал Чуф.\n\nНачался новый день.","question":"Что тебе нравится делать самым последним перед сном?","image":"assets/images/stories/posledniy-krug-parovozika-chufa-korotkaya.webp","audio":"","published":true},{"id":"3-7-01-dlinnaya","topicId":"3-7-01","slug":"festival-krivyh-vozdushnyh-zmeev-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Боюсь ошибиться","version":"Длинная","duration":"10–15 минут","title":"Фестиваль кривых воздушных змеев","hero":"лисёнок Нори","teaser":"Лисёнок Нори мечтает сделать самого аккуратного воздушного змея, но случайный кривой разрез приводит его к неожиданной идее.","text":"В Лисьей долине раз в году проходил Фестиваль воздушных змеев. Над лугом летали бумажные рыбы, драконы, бабочки и даже огромный полосатый носок.\n\nЛисёнок Нори ждал фестиваля целую неделю. Он разложил красную бумагу, ровные палочки, ленту и линейку.\n\n— Мой змей будет самым аккуратным. Ни одного кривого уголка!\n\nНори провёл линии и начал вырезать. Первый край вышел ровным. Второй — почти ровным. А на третьем ножницы вдруг ушли в сторону.\n\nЧик!\n\nНа бумаге появилась большая косая выемка.\n\nНори замер.\n\n— Всё испорчено.\n\nОн приложил отрезанный кусочек обратно. Щель всё равно была видна. Нори сел под стол. На лугу уже играла музыка, но идти туда ему расхотелось.\n\nВ дверь постучал дедушка. Он принёс катушку ниток и увидел скомканную красную бумагу.\n\n— Змей не получился, — сказал Нори.\n\nДедушка достал из коробки своего старого змея. Один бок у него был шире другого, на хвосте висели три разные ленты, а посередине красовалась заплатка в форме груши.\n\n— Он кривой, — удивился Нори.\n\n— Очень. Сначала он три раза падал в кусты. Потом я понял, что хвост слишком лёгкий. Добавил ленту. Потом ветер переворачивал его набок — появилась вот эта заплатка. А потом он полетел.\n\nНори снова посмотрел на косой разрез. Он вдруг заметил, что тот похож на открытую пасть.\n\n— А если это будет ветроед?\n\nМладшая сестра сразу прибежала.\n\n— Тогда ему нужны зубы!\n\nНори вырезал вторую маленькую выемку, нарисовал зубы и собрал змея. Бумага порвалась возле палочки — пришлось поставить заплатку. Нитка соскочила — Нори завязал другой узел. Хвост вышел короче, чем он хотел, и тогда к нему добавились три разноцветных лоскута.\n\n— Он уже совсем не аккуратный, — заметила сестра.\n\nНори посмотрел на красную морду.\n\n— Зато похож на настоящего ветроеда.\n\nНа лугу Нори поднял змея.\n\n— Один! Два! Три! — крикнула сестра.\n\nНори побежал.\n\nЗмей подпрыгнул и клюнул носом траву.\n\nЩёки Нори вспыхнули. Кто-то рядом хихикнул. Ему захотелось спрятать змея.\n\n— Что сказал ветер? — спросил дедушка.\n\nНори посмотрел внимательнее. Одна лента хвоста зацепилась за узел.\n\n— Наверное: «Распутай меня».\n\nОн распутал ленту и попробовал снова.\n\nНа этот раз змей поднялся, но резко ушёл влево.\n\n— Один бок тянет сильнее.\n\nНори передвинул узел на нитке.\n\nТретья попытка.\n\nОн побежал.\n\nФью-у-ух!\n\nВетроед поднялся над флажками, поймал поток воздуха и взлетел выше остальных. Косые зубы будто кусали облако.\n\n— Он правда ест ветер! — закричали дети.\n\nРядом белочка держала бабочку с помятым крылом.\n\n— Я хотела уйти, — сказала она. — Угол согнулся.\n\nНори посмотрел на помятое крыло.\n\n— А если там будет золотой узор?\n\nОни приклеили на угол золотое пятно. Бабочка снова полетела.\n\nЧерез час над лугом кружились змеи с заплатками, дополнительными хвостами, неожиданными ушами и одной совершенно случайной третьей лапой.\n\nВ конце фестиваля судья придумал новый приз — за самый интересный способ изменить то, что пошло не по плану. Его получил ветроед Нори.\n\nНори очень обрадовался. Но дома он больше всего смотрел не на приз.\n\nОн разгладил первый кривой обрезок красной бумаги и приклеил над столом.\n\nНе для того, чтобы помнить об ошибке.\n\nА потому что именно с этого косого кусочка однажды началась новая идея.\n\nЧерез несколько дней Нори снова мастерил. На этот раз он хотел сделать бумажную лодку с парусом. Всё шло хорошо, пока клей не оставил на белом парусе большое синее пятно.\n\nНори уже потянулся за новым листом. Потом остановился.\n\n— Похоже на облако, — сказала сестра.\n\n— Или на остров, — ответил Нори.\n\nОн дорисовал вокруг пятна тонкую линию, а рядом — маленькую лодку. Парус превратился в карту моря.\n\nЛодка всё равно должна была плавать, поэтому Нори проверил её в тазике. Сначала она заваливалась на бок. Он передвинул мачту. Потом парус тянул слишком сильно — Нори укоротил его.\n\nКогда лодка наконец поплыла, Нори заметил, что теперь реагирует на неудачи иначе. Сначала всё равно неприятно. Иногда очень. Но после первого «ой» у него появился новый вопрос:\n\n— Ну и что теперь можно с этим сделать?\n\nОн написал эту фразу на маленькой бумажке и положил в коробку с ножницами.\n\nРядом лежал красный обрезок от ветроеда.","question":"Если бы твоя ошибка могла превратиться во что-то интересное, что бы ты из неё придумал?","image":"assets/images/stories/festival-krivyh-vozdushnyh-zmeev-dlinnaya.webp","audio":"","published":true},{"id":"3-7-01-korotkaya","topicId":"3-7-01","slug":"festival-krivyh-vozdushnyh-zmeev-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Боюсь ошибиться","version":"Короткая","duration":"3–5 минут","title":"Фестиваль кривых воздушных змеев","hero":"лисёнок Нори","teaser":"Лисёнок Нори мечтает сделать самого аккуратного воздушного змея, но случайный кривой разрез приводит его к неожиданной идее.","text":"В Лисьей долине готовились к Фестивалю воздушных змеев.\n\nЛисёнок Нори хотел сделать самого аккуратного змея.\n\n— Ни одного кривого уголка!\n\nОн провёл линии и начал вырезать красную бумагу.\n\nЧик!\n\nНожницы вдруг ушли в сторону. На бумаге появилась большая косая выемка.\n\n— Всё испорчено, — прошептал Нори.\n\nНо дедушка показал ему своего первого змея. Тот был кривой, с разными лентами и большой заплаткой.\n\n— Он тоже вышел не таким, как я задумал, — сказал дедушка. — Зато потом полетел.\n\nНори посмотрел на свою выемку.\n\nОна была похожа на пасть.\n\n— А если это будет ветроед?\n\nОн добавил зубы, хвост из разноцветных лент и маленькую заплатку.\n\nНа лугу змей сразу упал.\n\nНори хотел уйти, но увидел: хвост запутался.\n\nОн распутал его.\n\nВо второй раз змея потянуло в сторону. Нори передвинул узел.\n\nВ третий раз красный ветроед поднялся высоко-высоко.\n\nФью-у-ух!\n\nКосая пасть будто кусала облако.\n\nРядом белочка грустила над помятым крылом своего змея.\n\n— А если сделать там золотой узор? — предложил Нори.\n\nК вечеру над лугом летали змеи с заплатками, разными хвостами и смешными неожиданными деталями.\n\nА первый кривой обрезок Нори потом приклеил над своим столом.\n\nИменно с него начался ветроед.\n\nЧерез несколько дней Нори снова мастерил и случайно поставил синее пятно на белом парусе бумажной лодки.\n\nОн почти взял новый лист, но сестра сказала:\n\n— Похоже на облако.\n\n— А мне — на остров.\n\nНори дорисовал море, и пятно стало частью карты.\n\nЛодка сначала кренилась, потом слишком резко поворачивала. Нори передвинул мачту и укоротил парус.\n\nКогда лодка поплыла, он написал на маленькой бумажке:\n\n«Что теперь можно с этим сделать?»\n\nИ положил её рядом с красным обрезком от ветроеда.","question":"Если бы твоя ошибка могла превратиться во что-то интересное, что бы ты из неё придумал?","image":"assets/images/stories/festival-krivyh-vozdushnyh-zmeev-korotkaya.webp","audio":"","published":true},{"id":"3-7-02-dlinnaya","topicId":"3-7-02","slug":"most-dlya-tryoh-svetlyachkov-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"У меня не получится","version":"Длинная","duration":"10–15 минут","title":"Мост для трёх светлячков","hero":"бобрёнок Тами","teaser":"Бобрёнок Тами уверен, что не умеет строить, пока маленький мост для светлячков не приходится создавать шаг за шагом.","text":"Бобрёнок Тами жил у широкой реки в семье знаменитых строителей. Папа строил плотины, бабушка — мосты, а дядя однажды сделал лестницу до самой верхушки старого дуба.\n\nТами тоже как-то попробовал построить табуретку. Она получилась с тремя ногами разной длины.\n\nПосле этого Тами решил:\n\n— Я не строитель.\n\nОн охотно носил ветки и подавал верёвки, но если кто-то говорил: «Попробуй сам», отвечал:\n\n— У меня не получится.\n\nОднажды вечером к берегу прилетели три светлячка. Ветер был сильным и не давал им перебраться через узкую канаву к поляне.\n\n— Там сегодня танец огоньков, — объяснили они. — Нам нужен совсем маленький мост.\n\nТами уже хотел сказать привычное «не получится», но посмотрел на крошечных светлячков.\n\n«Это ведь не плотина. Просто мостик».\n\nОн нашёл длинную ветку и положил через канаву.\n\nВетка скатилась.\n\n— Видите?\n\nПервый светлячок спросил:\n\n— А почему она скатилась?\n\nТами заметил круглый камень на краю и убрал его.\n\nВетка теперь лежала, но крутилась под лапками.\n\n— Почему? — спросил второй светлячок.\n\nТами вспомнил, как бабушка связывает несколько прутиков. Верёвки не было, зато рядом росла длинная трава.\n\nОн положил рядом три палочки и связал их травинками. Получилась плоская дорожка.\n\nПервый светлячок ступил на неё.\n\nМост прогнулся.\n\n— Ну вот, — вздохнул Тами.\n\nТретий светлячок посмотрел вниз:\n\n— А почему середина падает?\n\nТами прищурился.\n\n— Потому что ей не на что опереться.\n\nОн подложил под середину плоский камень.\n\nПотом решил проверить мост лапой.\n\nХрусть!\n\nОдна палочка сломалась.\n\nТами сел на землю.\n\n— Я же говорил.\n\nНо теперь ему уже было интересно. Он осмотрел сломанную палочку.\n\n— Эта была сухая.\n\nТами заменил её свежей, добавил ещё одну травинку и укрепил край маленьким камнем.\n\n— Теперь медленно.\n\nПервый светлячок пошёл.\n\nШаг.\n\nЕщё шаг.\n\nМост держался.\n\nЗа ним прошёл второй.\n\nТретий остановился ровно посередине и засветился так ярко, что весь мост стал золотым.\n\n— Работает!\n\nТами рассмеялся.\n\nСветлячки позвали его на танец.\n\n— Я не умею танцевать, — привычно сказал Тами.\n\nПотом замолчал.\n\n— Хотя… это я ещё не проверял.\n\nНа поляне он сначала наступил себе на хвост. Потом повернулся не туда. Но вскоре топал лапами и смеялся вместе со всеми.\n\nПоздно вечером папа увидел мост.\n\n— Это ты построил?\n\nТами перечислил:\n\n— Сначала ветка скатывалась. Потом крутилась. Потом мост прогнулся. Потом палочка сломалась.\n\n— Насыщенная стройка.\n\n— Да. Я каждый раз смотрел, почему не работает.\n\nНа следующий день Тами достал свою старую трёхногую табуретку. Покачал её.\n\n— Ну-ка, — сказал он. — А почему ты качаешься?\n\nИ принялся разбираться.\n\nЧерез неделю Тами решил всё-таки заняться старой табуреткой. Он поставил её на ровный пол и сел напротив, как будто табуретка была загадкой.\n\n— Почему качаешься?\n\nОдна ножка едва касалась пола. Тами подложил под неё кусочек коры. Качаться стало меньше.\n\n— Значит, дело в длине.\n\nОн позвал бабушку не для того, чтобы она сделала всё за него, а чтобы спросить, как правильно измерить ножки. Бабушка показала, как приложить палочку-шаблон.\n\nТами отпилил слишком мало. Потом ещё чуть-чуть. Потом понял, что одну ножку уже сделал короче нужного.\n\nОн засмеялся:\n\n— Отлично. Теперь у меня новая задача.\n\nВместо того чтобы выбросить табуретку, Тами сделал четыре одинаковые накладки снизу. Табуретка встала ровно.\n\nНа ней по-прежнему была царапина, одна ножка отличалась цветом, а сбоку торчал узел.\n\nТами поставил её возле окна.\n\nТри светлячка прилетели вечером и сели на спинку.\n\n— Красиво, — сказал первый.\n\n— Ровно, — сказал второй.\n\n— А главное, не с первого раза, — добавил Тами.","question":"Какое большое дело тебе было бы легче начать, если разделить его на маленькие шаги?","image":"assets/images/stories/most-dlya-tryoh-svetlyachkov-dlinnaya.webp","audio":"","published":true},{"id":"3-7-02-korotkaya","topicId":"3-7-02","slug":"most-dlya-tryoh-svetlyachkov-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"У меня не получится","version":"Короткая","duration":"3–5 минут","title":"Мост для трёх светлячков","hero":"бобрёнок Тами","teaser":"Бобрёнок Тами уверен, что не умеет строить, пока маленький мост для светлячков не приходится создавать шаг за шагом.","text":"Бобрёнок Тами жил в семье строителей.\n\nПапа строил плотины, бабушка — мосты.\n\nА Тами однажды сделал кривую табуретку и решил:\n\n— У меня ничего не получится.\n\nОднажды три светлячка попросили помочь им перейти канаву. Ветер не давал перелететь.\n\nТами положил через канаву ветку.\n\nОна скатилась.\n\n— Вот видите!\n\nНо светлячок спросил:\n\n— Почему?\n\nТами убрал круглый камень.\n\nВетка перестала скатываться, но начала крутиться.\n\nТами связал три палочки травинками. Получился плоский мост.\n\nОн прогнулся.\n\nТами подложил под середину камень.\n\nХрусть!\n\nОдна сухая палочка сломалась.\n\n— Ну вот…\n\nТами заменил её свежей.\n\nНаконец первый светлячок прошёл.\n\nПотом второй.\n\nА третий остановился посередине и засветился так ярко, что мост стал золотым.\n\n— Работает!\n\nВечером папа спросил:\n\n— Ты построил мост?\n\n— Сначала всё было не так, — сказал Тами. — Но я каждый раз смотрел, почему не работает.\n\nНа следующий день он достал свою старую кривую табуретку.\n\nПокачал её и спросил:\n\n— А почему ты качаешься?\n\nЧерез неделю Тами снова достал кривую табуретку.\n\n— Почему ты качаешься?\n\nОказалось, одна ножка короче другой.\n\nТами попросил бабушку показать, как измерять, а дальше правил сам. Один раз отпилил мало, потом чуть больше, а одну ножку сделал слишком короткой.\n\n— Новая задача, — сказал он.\n\nТами добавил снизу одинаковые накладки, и табуретка перестала качаться.\n\nВечером на неё сели три светлячка.\n\n— Ровно! — сказали они.\n\n— И не с первого раза, — ответил Тами.","question":"Какое большое дело тебе было бы легче начать, если разделить его на маленькие шаги?","image":"assets/images/stories/most-dlya-tryoh-svetlyachkov-korotkaya.webp","audio":"","published":true},{"id":"3-7-03-dlinnaya","topicId":"3-7-03","slug":"kubok-kotoryy-ukatilsya-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Не хочу проигрывать","version":"Длинная","duration":"10–15 минут","title":"Кубок, который укатился","hero":"сурок Мико","teaser":"Сурок Мико так хочет выиграть лесную гонку, что забывает замечать саму игру — пока кубок неожиданно не отправляется в собственное путешествие.","text":"Каждую субботу в Ореховой роще устраивали гонки на маленьких тележках. Тележки были самые разные: из коробок, корзинок и старых ящиков. У одной вместо руля был деревянный круг, у другой на боку звенел колокольчик.\n\nСурок Мико приходил раньше всех. Он протирал колёса, проверял верёвку и три раза проходил трассу пешком.\n\nМико очень любил выигрывать.\n\nКогда он приезжал первым, внутри у него всё звенело: «Да! Я смог!»\n\nА если первым был кто-то другой, внутри звенело совсем иначе: «Нет! Так не должно быть!»\n\nВ эту субботу на пеньке стоял новый блестящий кубок.\n\n— Победителю! — объявил барсук-судья.\n\nМико смотрел только на кубок.\n\nЗайчиха Сола показала ему свою тележку с маленькой пищалкой.\n\n— Смотри!\n\nПи-и!\n\n— Не мешай, — ответил Мико. — Я готовлюсь выигрывать.\n\nНа старт вышли пять тележек.\n\n— Раз! Два! Три!\n\nШ-ш-шух!\n\nНа первом повороте Мико был впереди. На втором Сола догнала его. На третьем её тележка смешно пискнула:\n\nПи-и!\n\nМико отвлёкся на секунду. Его колесо попало в мягкую землю, тележка замедлилась, и Сола пересекла финиш первой.\n\nМико приехал вторым.\n\nВсе закричали:\n\n— Ура!\n\nСола прыгала от радости:\n\n— Мико, ты видел мой поворот?\n\nНо Мико смотрел на кубок.\n\n— Нечестно!\n\n— Почему? — удивился судья.\n\n— Меня задержала земля! И её пищалка отвлекла!\n\nСола перестала улыбаться.\n\n— Я не специально.\n\nМико пнул шишку. Ему хотелось или немедленно переиграть гонку, или уйти домой.\n\nИ тут случилось странное.\n\nСола поставила кубок на край пенька, чтобы поправить флажок. Подул ветер. Кубок дрогнул.\n\nПлюх!\n\nОн упал на траву и покатился вниз по склону.\n\n— Кубок!\n\nВсе бросились за ним.\n\nКубок оказался очень проворным. Он проскочил между корней, подпрыгнул на камне и покатился к ручью.\n\n— Перехватывай справа! — крикнул Мико.\n\nСола побежала справа. Белка Рико полезла по поваленному стволу. Ёжик Дым встал у воды.\n\nКубок вылетел из травы.\n\nМико прыгнул — не достал.\n\nСола вытянула лапу — тоже не достала.\n\nКубок стукнулся о камень и полетел прямо в ручей.\n\nНо Дым успел подставить корзинку.\n\nДзынь!\n\nКубок оказался внутри.\n\nВсе остановились, а потом одновременно расхохотались.\n\n— Вот это была гонка! — выдохнула Сола.\n\n— И кубок пришёл последним, — сказал Рико.\n\nМико тоже засмеялся. Он вдруг заметил, что последние пять минут вообще не думал, кто первый.\n\nБарсук вытер кубок и снова отдал его Соле.\n\nМико посмотрел на неё. Ему всё ещё хотелось выиграть. Но теперь он уже не хотел отнимать её победу.\n\n— Давай ещё одну гонку?\n\nСола насторожилась:\n\n— Чтобы решить, чей кубок?\n\n— Нет. Кубок твой. Просто хочу пройти тот поворот лучше.\n\nСола улыбнулась.\n\n— Тогда покажу, как я делаю.\n\nОна нарисовала лапкой линию на земле:\n\n— Здесь не торможу. А тут поворачиваю раньше.\n\n— А я быстрее на прямой, — сказал Мико. — Могу показать.\n\nОни обменялись советами.\n\nВо второй гонке первым приехал Рико. Мико был третьим.\n\nОн поморщился. На секунду захотелось сказать: «Ещё раз!»\n\nНо вместо этого он спросил:\n\n— Рико, как ты так быстро прошёл мостик?\n\nЧерез час они гоняли уже без судьи и без кубка. Соревновались, кто точнее остановится возле шишки, у кого смешнее разворот и кто дальше проедет задом.\n\nМико выиграл остановку у шишки. Проиграл езду задом. А в последней гонке его тележка вообще повернула не туда и въехала в куст малины.\n\nИз куста торчал только хвост.\n\nСола спросила:\n\n— Ты как?\n\nМико выполз весь в листьях.\n\n— Кажется, куст выиграл.\n\nВсе покатились со смеху.\n\nВечером Мико проходил мимо пустого пенька. Кубок уже унесла Сола.\n\nНо день почему-то совсем не казался пустым.\n\nМико всё ещё хотел приезжать первым.\n\nПросто теперь ему было интересно ещё и то, что случится по дороге.\n\nНа следующей субботе Мико снова готовился к гонке серьёзно. Он смазал колёса, потренировал поворот и даже придумал новую ручку для тормоза.\n\nПеред стартом он заметил, что волнуется.\n\nКубок снова стоял на пеньке.\n\nМико хотел его. Очень.\n\n— Я попробую выиграть, — сказал он Соле.\n\n— Я тоже.\n\n— Только сегодня без побега кубка.\n\n— Договорились.\n\nГонка началась. На втором повороте Мико вырвался вперёд. Потом его догнал Рико. До финиша оставалось совсем немного.\n\nМико приехал первым.\n\nОн подпрыгнул так высоко, что едва не перевернул тележку.\n\n— Да!\n\nПобеда была такой же приятной, как раньше. Может быть, даже приятнее.\n\nНо через минуту Мико уже спрашивал Рико:\n\n— Где я тебя обогнал?\n\nА потом они вместе разбирали поворот.\n\nМико понял одну важную для себя вещь без всяких объявлений судьи: научиться проигрывать не означало перестать хотеть победить.\n\nМожно было очень хотеть первым пересечь финиш — и всё равно оставить место для следующей гонки, чужого успеха и смеха над малиновым кустом.","question":"Что в игре тебе нравится даже тогда, когда выигрывает кто-то другой?","image":"assets/images/stories/kubok-kotoryy-ukatilsya-dlinnaya.webp","audio":"","published":true},{"id":"3-7-03-korotkaya","topicId":"3-7-03","slug":"kubok-kotoryy-ukatilsya-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Не хочу проигрывать","version":"Короткая","duration":"3–5 минут","title":"Кубок, который укатился","hero":"сурок Мико","teaser":"Сурок Мико так хочет выиграть лесную гонку, что забывает замечать саму игру — пока кубок неожиданно не отправляется в собственное путешествие.","text":"В Ореховой роще проходили гонки на тележках.\n\nСурок Мико очень любил выигрывать. В этот раз победителю обещали блестящий кубок.\n\n— Он будет мой, — решил Мико.\n\nНа старте он мчался первым. Но на повороте отвлёкся, колесо попало в мягкую землю, и зайчиха Сола приехала раньше.\n\n— Нечестно! — вспыхнул Мико.\n\nИ тут кубок, который стоял на пеньке, качнулся от ветра.\n\nПлюх!\n\nОн упал и покатился вниз с холма.\n\n— Кубок!\n\nВсе побежали за ним.\n\nКубок прыгал по камням, катился между корней и полетел прямо к ручью.\n\n— Справа! — крикнул Мико.\n\nСола побежала справа, а ёжик Дым встал у воды.\n\nКубок почти упал в ручей, но Дым поймал его корзинкой.\n\nДзынь!\n\nВсе рассмеялись.\n\n— Вот это была гонка! — сказала Сола.\n\nМико вдруг заметил: пока они ловили кубок, он вообще не думал, кто первый.\n\n— Давай ещё одну гонку? — предложил он.\n\n— За кубок?\n\n— Нет. Кубок твой. Я хочу попробовать поворот ещё раз.\n\nВо второй гонке Мико пришёл третьим. Ему это не очень понравилось.\n\nНо вместо «нечестно» он спросил победителя:\n\n— Как ты так быстро прошёл мостик?\n\nА потом они гоняли задом, останавливались возле шишки и однажды Мико въехал прямо в малиновый куст.\n\n— Кажется, куст выиграл! — сказал он, вылезая весь в листьях.\n\nНа следующей гонке Мико снова очень хотел выиграть.\n\nИ на этот раз он действительно приехал первым.\n\n— Да! — закричал он и подпрыгнул.\n\nПобеда всё ещё была невероятно приятной.\n\nНо уже через минуту Мико спрашивал у Рико:\n\n— Где я тебя обогнал?\n\nОни вместе разбирали поворот.\n\nМико не перестал хотеть побеждать. Просто теперь проигрыш уже не делал всю игру плохой, а победа не мешала ему интересоваться, как ехали другие.","question":"Что в игре тебе нравится даже тогда, когда выигрывает кто-то другой?","image":"assets/images/stories/kubok-kotoryy-ukatilsya-korotkaya.webp","audio":"","published":true},{"id":"3-7-04-dlinnaya","topicId":"3-7-04","slug":"odin-fonar-na-dvoih-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Не хочу делиться","version":"Длинная","duration":"10–15 минут","title":"Один фонарь на двоих","hero":"совёнок Пип","teaser":"Совёнок Пип не хочет отдавать любимый звёздный фонарь, но сам придумывает способ играть вместе и не терять важную для него вещь.","text":"У совёнка Пипа был звёздный фонарь. Если поставить его на пол и повернуть маленькое колёсико, на потолке появлялись звёзды: синие, жёлтые, круглые и с хвостиками.\n\nПип получил фонарь на день рождения и очень его берёг. Сам нажимал кнопку. Сам менял бумажные диски. Сам убирал фонарь на верхнюю полку.\n\nОднажды к Пипу пришла белочка Тая.\n\n— Покажешь звёзды?\n\n— Покажу.\n\nПип выключил свет.\n\nЩёлк.\n\nНа потолке вспыхнуло маленькое небо.\n\n— Ой! А можно я покручу? — спросила Тая.\n\nПип сразу прижал фонарь крыльями.\n\n— Нет.\n\n— Я аккуратно.\n\n— Всё равно нет.\n\nТая увидела коробку с дисками.\n\n— А этот с кометами можно поставить?\n\n— Нет!\n\nПип придвинул коробку к себе.\n\n— Тогда во что будем играть? — спросила Тая.\n\n— В звёзды.\n\n— Но ты всё делаешь сам.\n\nПип нахмурился. Он не хотел обижать Таю. Просто однажды маленький кузен схватил фонарь липкими лапами, уронил крышку, и на корпусе осталась царапина. Пип до сих пор её замечал.\n\n— Это мой фонарь, — сказал он.\n\n— Я знаю. Я же не забираю его домой.\n\nТая подошла к окну.\n\nЗа окном как раз начинался Метеорный дождь. По небу прошла светлая полоска.\n\nФью!\n\n— Давай сделаем комнату как небо! — предложила Тая. — Настоящие звёзды за окном, твои — на потолке. А я сделаю бумажные кометы.\n\nПипу идея понравилась.\n\nТая нарезала серебристые полоски и прикрепила их к бумажным звёздам.\n\n— А можно я хотя бы выберу диск? — спросила она.\n\nПип посмотрел на коробку. Один диск был самым любимым — с большими жёлтыми звёздами.\n\n— Любимый я буду ставить сам, — решил он. — А из этих трёх ты можешь выбрать.\n\n— Кометы!\n\n— Держи за края.\n\nТая взяла диск двумя лапками.\n\n— Так?\n\n— Так.\n\nОна вставила его немного криво и остановилась.\n\n— Кажется, не вошло.\n\n— Поверни чуть-чуть.\n\nЩёлк.\n\nДиск встал на место.\n\n— Получилось!\n\nНичего не сломалось.\n\nОни включили фонарь. По потолку побежали кометы. Сначала Пип крутил колёсико, а Тая двигала бумажную звезду по стене. Потом поменялись.\n\n— Только медленно, — попросил Пип.\n\n— Хорошо.\n\nЗвёзды поплыли по потолку.\n\nВдруг за окном пролетела особенно яркая звезда.\n\nФью-у-у!\n\nТая ахнула и нечаянно задела коробку.\n\nДиски посыпались на пол.\n\n— Ой!\n\nОни оба замерли.\n\n— Я случайно. Прости, — сказала Тая.\n\nПип поднял любимый диск. Он был цел. На другом появилась маленькая складка.\n\nПип расстроился.\n\n— Вот поэтому я не хотел…\n\nТая опустила уши.\n\nПип разгладил складку лапкой. Она почти исчезла.\n\n— Давай коробку поставим подальше от края, — сказал он.\n\nОни вместе переставили её и продолжили игру.\n\nПозже Пип нарисовал правила для своего фонаря: любимый диск он ставит сам, остальные можно брать чистыми лапами, фонарь не носят по комнате, а если хочется что-то попробовать — сначала спрашивают.\n\nНа следующий день пришли ещё двое друзей.\n\n— Можно фонарь?\n\nПип посмотрел на любимую вещь. Ему всё ещё не хотелось отдавать её просто так.\n\nИ он не обязан был.\n\n— Я покажу, как с ним играть, — сказал Пип. — А потом выберем, кто крутит первым.\n\nВечером на потолке появилось созвездие «Белка с огромным хвостом», «Совёнок, который съел семь печений» и ещё одно, которое придумал Пип:\n\n«Фонарь, вокруг которого всем хватило места».\n\nЧерез несколько дней Тая принесла свою любимую вещь — маленькую музыкальную шкатулку.\n\n— Теперь моя очередь переживать, — сказала она.\n\nПип засмеялся.\n\nШкатулка открывалась только если повернуть крошечный ключ. Пип сразу хотел попробовать.\n\n— Можно?\n\nТая прижала шкатулку к себе.\n\n— Только я буду заводить. А ты можешь выбрать мелодию из двух дисков.\n\nПип удивился: её правило было почти как его правило про любимый звёздный диск.\n\n— Хорошо.\n\nОни играли осторожно. Пип не обиделся, что Тая не дала ему крутить ключ.\n\nТеперь он лучше понимал: «делиться» не всегда значит отдать всё в чужие руки. Иногда это значит пустить другого человека в свою игру настолько, насколько тебе спокойно.\n\nВечером Пип добавил к своим картинкам возле полки ещё одну:\n\nдве лапы держат одну звезду, но каждая — за свой край.","question":"Как можно играть вместе с любимой вещью так, чтобы тебе тоже было спокойно?","image":"assets/images/stories/odin-fonar-na-dvoih-dlinnaya.webp","audio":"","published":true},{"id":"3-7-04-korotkaya","topicId":"3-7-04","slug":"odin-fonar-na-dvoih-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Не хочу делиться","version":"Короткая","duration":"3–5 минут","title":"Один фонарь на двоих","hero":"совёнок Пип","teaser":"Совёнок Пип не хочет отдавать любимый звёздный фонарь, но сам придумывает способ играть вместе и не терять важную для него вещь.","text":"У совёнка Пипа был любимый звёздный фонарь.\n\nОн светил на потолок синими и жёлтыми звёздами.\n\nОднажды в гости пришла белочка Тая.\n\n— Можно я покручу колёсико?\n\nПип прижал фонарь к себе.\n\n— Нет.\n\n— А диск с кометами поставить?\n\n— Нет.\n\nТая вздохнула:\n\n— Тогда ты играешь, а я только смотрю.\n\nПип боялся, что фонарь уронят или поцарапают.\n\nТут за окном начался настоящий метеорный дождь.\n\n— Давай сделаем целое небо! — предложила Тая.\n\nОна вырезала бумажные кометы.\n\nПип подумал и сказал:\n\n— Мой самый любимый диск я буду ставить сам. А из остальных ты можешь выбрать.\n\n— Кометы!\n\nТая аккуратно взяла диск за края и вставила его.\n\nЩёлк.\n\nПолучилось.\n\nПотом Пип крутил фонарь, а Тая двигала бумажные звёзды. Потом они поменялись.\n\nВдруг Тая случайно задела коробку. Диски упали.\n\n— Прости!\n\nОдин диск чуть помялся.\n\nПип разгладил его.\n\n— Давай поставим коробку подальше от края.\n\nОни продолжили играть.\n\nПозже Пип придумал правила: фонарь не носят по комнате, диски берут чистыми лапами, а любимый диск Пип ставит сам.\n\nТак фонарь остался его любимой вещью.\n\nА созвездий на потолке стало больше, потому что теперь их придумывали вдвоём.\n\nЧерез несколько дней Тая принесла свою любимую музыкальную шкатулку.\n\nПип попросил:\n\n— Можно я заведу?\n\nТая прижала её к себе.\n\n— Ключ кручу только я. А ты можешь выбрать мелодию.\n\nПип не обиделся. Это было похоже на его правило про любимый диск.\n\nОни слушали шкатулку вместе.\n\nПип понял, что совместная игра не обязательно означает «отдать всё». Можно самому решать, чем и как ты готов делиться.","question":"Как можно играть вместе с любимой вещью так, чтобы тебе тоже было спокойно?","image":"assets/images/stories/odin-fonar-na-dvoih-korotkaya.webp","audio":"","published":true},{"id":"3-7-05-dlinnaya","topicId":"3-7-05","slug":"drakonchik-i-karman-svetyaschihsya-kamney-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Хочу всё себе","version":"Длинная","duration":"10–15 минут","title":"Дракончик и карман светящихся камней","hero":"дракончик Эйво","teaser":"Дракончик Эйво старается собрать все светящиеся камни, потому что боится остаться без самого красивого, и выясняет, сколько ему действительно нужно.","text":"Раз в месяц в Долине драконов открывалась Пещера светляных камней.\n\nЗелёные камни светились, как мох после дождя. Голубые — как вечернее небо. Оранжевые — как маленькие огоньки.\n\nКаждому дракончику разрешалось выбрать несколько камней для игр и поделок.\n\nЭйво пришёл первым. Он увидел россыпь света и сразу подумал:\n\n«А вдруг самый красивый возьмёт кто-то другой?»\n\nОн поднял голубой камень. Потом зелёный. Потом два оранжевых. Потом сиреневый.\n\n— Хватит? — спросила хранительница.\n\nЭйво увидел золотой камень за валуном.\n\n— Ещё этот.\n\nСкоро оба кармана оттопырились. Эйво набрал камней в капюшон, один зажал под крылом, ещё два нёс в лапах.\n\nДруг Эйво, дракончик Рум, выбрал всего два.\n\n— Пойдём делать фонари?\n\n— Подожди. Я ещё выбираю.\n\n— Ты уже почти всю пещеру несёшь.\n\n— Зато у меня будут все красивые.\n\nЭйво сделал шаг.\n\nДзынь!\n\nКамень выпал. Он наклонился поднять его — из капюшона выкатились ещё три. Пока собирал их, из кармана выпали два оранжевых.\n\nНаконец он дошёл до деревянного мостика.\n\nКарманы тянули вниз. Капюшон съехал на глаза.\n\nОдин камень выскользнул из-под крыла.\n\nПлюх!\n\nОн упал в ручей.\n\n— Мой золотой!\n\nЭйво бросился к краю. Рум успел поймать его за хвост.\n\n— Достанем палкой.\n\nЧтобы наклониться, Эйво пришлось освободить лапы.\n\n— Подержи два, — неохотно сказал он.\n\nРум взял два.\n\nЭйво всё ещё был слишком тяжёлым.\n\n— Ещё два.\n\nРум взял ещё.\n\nОни подтолкнули золотой камень к берегу длинной веткой.\n\n— Есть!\n\nРум сразу вернул все четыре камня.\n\nЭйво удивился. Ничего у него не отняли.\n\nВ мастерской остальные уже делали поделки. Кто-то складывал дорожку, кто-то поставил голубой камень в бумажный домик.\n\nЭйво высыпал свою гору на стол.\n\nДзынь-дзынь-дзынь!\n\nКамней было так много, что для поделки почти не осталось места.\n\nОн хотел сделать башню — камни разъезжались.\n\nХотел узор — не помещался.\n\nХотел фонарь — не мог выбрать камень.\n\n— Голубой красивый. Но золотой красивее. А зелёный тоже нужен…\n\nЧерез некоторое время все мастерили, а Эйво всё ещё перекладывал свою гору.\n\nМаленькая драконица Сиа спросила:\n\n— Можно один оранжевый? Мне не хватает солнышка для домика.\n\nЭйво автоматически накрыл камни крылом.\n\n— Нет.\n\nСиа ушла.\n\nЭйво посмотрел на оранжевые камни. Их было семь.\n\nОн выбрал один самый яркий и один с красивой полоской. Остальные просто лежали.\n\nЭйво вспомнил тяжёлые карманы и капюшон на глазах.\n\n— Сиа!\n\nОна вернулась.\n\nЭйво протянул один камень.\n\n— Вот.\n\nСиа вставила его в крышу бумажного домика. Получилось маленькое солнце.\n\nКамень не исчез. Он просто светился теперь в другом месте.\n\nЭйво разложил свою гору на три кучки:\n\n«Точно хочу».\n\n«Может пригодиться».\n\n«Просто схватил».\n\nВ первой осталось пять камней.\n\nИз них Эйво сделал светящегося дракона. Золотой камень стал сердцем, голубые — крыльями, зелёный — хвостом.\n\nЧасть остальных он вернул в пещеру. Несколько обменял. Один оставил Сие.\n\nВ карманах стало легко.\n\nНа следующий месяц Эйво увидел новый красный камень. Очень красивый.\n\nОн уже протянул лапу, но остановился.\n\n— А что я хочу из него сделать?\n\nИ только потом взял его.\n\nЧерез несколько недель в долине устроили обменный день. Каждый мог принести вещь, которой больше не пользуется, и поменять на другую.\n\nЭйво долго выбирал, что взять. Раньше он бы принёс пустую сумку, чтобы унести как можно больше.\n\nТеперь он положил туда два светляных камня, которые так и лежали без дела, и старую фигурку.\n\nНа обмене ему понравилось сразу пять вещей.\n\nКрасная лента.\n\nМаленькая лупа.\n\nСтеклянный шарик.\n\nСмешной свисток.\n\nИ набор миниатюрных кисточек.\n\nЭйво почувствовал знакомое: «Хочу всё».\n\nОн даже улыбнулся.\n\n— Привет, старое чувство.\n\nПотом представил свои карманы и выбрал кисточки. Они как раз подходили для следующей поделки.\n\nКрасная лента досталась Сие. Свисток — Руму.\n\nПо дороге домой они по очереди свистели так громко, что птицы взлетали с кустов.\n\nЭйво нёс всего одну новую вещь.\n\nНо в голове уже было пять идей, что можно ею нарисовать.","question":"Если бы ты нашёл целую корзину сокровищ, какие три вещи ты точно захотел бы оставить себе?","image":"assets/images/stories/drakonchik-i-karman-svetyaschihsya-kamney-dlinnaya.webp","audio":"","published":true},{"id":"3-7-05-korotkaya","topicId":"3-7-05","slug":"drakonchik-i-karman-svetyaschihsya-kamney-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Хочу всё себе","version":"Короткая","duration":"3–5 минут","title":"Дракончик и карман светящихся камней","hero":"дракончик Эйво","teaser":"Дракончик Эйво старается собрать все светящиеся камни, потому что боится остаться без самого красивого, и выясняет, сколько ему действительно нужно.","text":"В Пещере светляных камней дракончик Эйво увидел сотни сокровищ.\n\nГолубые сияли, как небо. Зелёные — как мох. Оранжевые — как огоньки.\n\nЭйво подумал:\n\n«А вдруг самый красивый возьмёт кто-то другой?»\n\nОн набил камнями карманы, капюшон и даже зажал один под крылом.\n\nПо дороге камни выпадали:\n\nДзынь! Дзынь!\n\nНа мостике золотой камень выскользнул и упал в ручей.\n\n— Мой!\n\nЧтобы достать его, Эйво попросил друга Рума подержать несколько камней.\n\nРум помог и потом всё вернул.\n\nВ мастерской Эйво высыпал целую гору. Но места для поделки не осталось.\n\nМаленькая драконица Сиа попросила один оранжевый камень для бумажного домика.\n\nУ Эйво их было семь.\n\nОн выбрал один и протянул ей.\n\nСиа сделала из него маленькое солнце.\n\nЭйво разложил остальные камни на три кучки:\n\n«Точно хочу».\n\n«Может пригодиться».\n\n«Просто схватил».\n\nВ первой осталось пять.\n\nИз них он сделал светящегося дракона с золотым сердцем.\n\nА когда пещера открылась снова, Эйво увидел новый красный камень.\n\nОн уже протянул лапу, но сначала спросил:\n\n— А что я хочу из него сделать?\n\nНа обменном дне Эйво снова увидел сразу много красивого: ленту, лупу, свисток, шарик и кисточки.\n\nВнутри сразу появилось знакомое:\n\n«Хочу всё!»\n\nЭйво улыбнулся и подумал, чем он правда будет пользоваться.\n\nВыбрал кисточки.\n\nСвисток взял Рум, а ленту — Сиа.\n\nПо дороге домой друзья по очереди свистели и смеялись.\n\nЭйво нёс одну новую вещь, зато уже придумал пять картинок, которые хотел ею нарисовать.","question":"Если бы ты нашёл целую корзину сокровищ, какие три вещи ты точно захотел бы оставить себе?","image":"assets/images/stories/drakonchik-i-karman-svetyaschihsya-kamney-korotkaya.webp","audio":"","published":true},{"id":"3-7-06-dlinnaya","topicId":"3-7-06","slug":"sad-kotoryy-zvuchal-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Завидую другому ребёнку","version":"Длинная","duration":"10–15 минут","title":"Сад, который звучал","hero":"мышка Лета","teaser":"Мышка Лета так засматривается на великолепную работу соседки, что почти бросает свою — пока ветер не показывает, чем её идея отличается.","text":"В городе Маленьких Мастеров готовилась выставка «Сделано своими лапами».\n\nМышка Лета решила создать сад в коробке. Она посадила туда мох, сделала дорожку из фасолинок и повесила над садом маленькие колокольчики из желудевых шапочек.\n\nКогда ветер проходил через окно, они тихо звенели:\n\nтинь… тинь…\n\nЛете нравилось.\n\nНо утром на выставку пришла белочка Зара и принесла огромный замок. В нём были башни, мост, флажки и даже маленькая дверца, которая открывалась на ниточке.\n\nВсе сразу окружили замок.\n\n— Вот это да!\n\n— Какая башня!\n\n— А мост двигается!\n\nЛета посмотрела на свой сад.\n\nКоробка.\n\nМох.\n\nФасолинки.\n\nТри маленьких колокольчика.\n\nВ груди стало неприятно.\n\n«Почему я не сделала замок? Почему у меня всё такое маленькое?»\n\nЛета вернулась домой и стала срочно переделывать сад.\n\nОна поставила в коробку башню из картона.\n\nБашня упала на мох.\n\nЛета приклеила мост.\n\nМост закрыл дорожку.\n\nОна добавила флажки.\n\nКолокольчики перестали звенеть, потому что ленты запутались в них.\n\n— Так лучше? — спросил папа.\n\n— Не знаю.\n\nНа следующий день Лета увидела, что Зара добавила к замку светящийся фонарь.\n\n«У неё ещё и свет!»\n\nЛета побежала домой и приклеила над садом маленький фонарик. Он оказался слишком тяжёлым, крыша коробки согнулась.\n\nЛета сердито сняла его.\n\n— Я вообще не понесу сад.\n\nПапа не стал убеждать её, что её работа «самая лучшая».\n\nОн спросил:\n\n— А что тебе в ней нравилось до того, как ты увидела замок?\n\nЛета задумалась.\n\n— Когда ветер шёл, желуди звенели.\n\nОна осторожно сняла лишние башни и флажки.\n\nРаспутала ленты.\n\nТинь…\n\nОдин колокольчик снова зазвенел.\n\nЛета поставила коробку у окна.\n\nПришёл ветер.\n\nМох чуть дрогнул.\n\nТри желудевые шапочки закачались.\n\nТинь… тинь-тинь…\n\nЛета закрыла глаза.\n\nБудто маленький сад разговаривал.\n\nНа выставке она поставила коробку в самом конце длинного стола. Сначала рядом снова толпились у замка Зары.\n\nЛета старалась туда не смотреть.\n\nПотом дверь открылась, и по залу прошёл сквозняк.\n\nТинь…\n\nОдин ребёнок повернул голову.\n\nТинь-тинь…\n\n— А где это?\n\nОн подошёл к саду.\n\nЛета показала:\n\n— Тут ветер играет.\n\nРебёнок подул.\n\nФью.\n\nКолокольчики ответили.\n\nТинь!\n\nСкоро возле сада тоже стояли дети. Они дули то сильно, то тихо и слушали, как меняется звук.\n\nЗара подошла последней.\n\n— Можно попробовать?\n\nЛета удивилась.\n\n— Конечно.\n\nЗара подула на колокольчики.\n\n— Красиво. А у меня замок вообще не звучит.\n\nЛета посмотрела на её башни.\n\nЗависть не исчезла сразу. Ей всё ещё очень нравился высокий замок.\n\n— Зато у тебя дверь открывается, — сказала она.\n\n— Хочешь посмотреть механизм?\n\n— Хочу.\n\nПосле выставки девочки сели рядом. Зара показала ниточку внутри башни. Лета показала, как подбирала желудевые шапочки разного размера, чтобы они звучали по-разному.\n\nОни даже придумали поставить маленький звенящий сад во двор замка — просто для игры, не для конкурса.\n\nКогда Лета вечером несла домой свою коробку, она снова увидела большой замок Зары.\n\nЗамок всё ещё был великолепный.\n\nНо теперь рядом с мыслью «хочу такой же» появилась другая:\n\n«А мой сад умеет разговаривать с ветром».\n\nИ эта мысль тоже заняла своё место.\n\nЧерез несколько дней Лета снова пришла в мастерскую. На соседнем столе мальчик-крот делал огромный корабль из дерева.\n\nЛета поймала себя на знакомом взгляде:\n\n«У него большой. У меня маленькое».\n\nОна не ругала себя за эту мысль. Просто вернулась к своей работе — новому саду, где хотела сделать дорожку, которая шуршит под пальцами.\n\nКрот подошёл:\n\n— А чем это ты посыпала?\n\n— Сухими семенами. Слышишь?\n\nШ-ш-ш.\n\n— Классно. У меня корабль большой, но его нельзя трогать — мачта падает.\n\nЛета засмеялась.\n\nОни помогли друг другу: Лета придумала для корабля мягкую подставку, а крот вырезал ей маленькую деревянную скамейку.\n\nНа новой выставке рядом стояли два очень разных проекта.\n\nЛета всё ещё иногда сравнивала.\n\nНо теперь сравнение не всегда заканчивалось словами «у меня хуже».\n\nИногда оно превращалось в вопрос:\n\n«А что интересного есть у него? А что — у меня?»","question":"Бывало ли у тебя, что чужая вещь или умение казались лучше твоих? Что в твоём тогда всё-таки было особенного?","image":"assets/images/stories/sad-kotoryy-zvuchal-dlinnaya.webp","audio":"","published":true},{"id":"3-7-06-korotkaya","topicId":"3-7-06","slug":"sad-kotoryy-zvuchal-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Завидую другому ребёнку","version":"Короткая","duration":"3–5 минут","title":"Сад, который звучал","hero":"мышка Лета","teaser":"Мышка Лета так засматривается на великолепную работу соседки, что почти бросает свою — пока ветер не показывает, чем её идея отличается.","text":"Мышка Лета сделала для выставки маленький сад в коробке.\n\nВ нём был мох, дорожка из фасолинок и три колокольчика из желудевых шапочек.\n\nКогда дул ветер:\n\nтинь… тинь…\n\nНо потом Лета увидела работу белочки Зары — огромный замок с башнями и мостом.\n\nВсе ахнули:\n\n— Вот это да!\n\nЛета посмотрела на свой маленький сад и подумала:\n\n«Почему у меня не так красиво?»\n\nОна стала добавлять башни, флажки и фонарик.\n\nБашня падала на мох.\n\nФлажки путались в колокольчиках.\n\nФонарик гнул крышу.\n\nНаконец Лета сняла всё лишнее.\n\n— Что мне нравилось раньше? — спросила она себя.\n\nОна поставила сад у окна.\n\nПришёл ветер.\n\nТинь… тинь-тинь…\n\nКолокольчики снова зазвучали.\n\nНа выставке все сначала смотрели на замок Зары.\n\nНо потом в дверь подул сквозняк.\n\nТинь!\n\nДети услышали сад Леты и подошли.\n\n— А можно подуть?\n\nФью!\n\nТинь-тинь!\n\nДаже Зара попросила попробовать.\n\n— Красиво, — сказала она. — Мой замок совсем не звучит.\n\nЛета улыбнулась.\n\nЗамок Зары всё ещё ей очень нравился.\n\nНо теперь она помнила: её маленький сад умел то, чего не умел никакой замок.\n\nОн разговаривал с ветром.\n\nЧерез несколько дней Лета увидела огромный деревянный корабль другого мастера и снова подумала:\n\n«Мой проект такой маленький».\n\nПотом мальчик-крот подошёл к её новому саду.\n\n— А почему дорожка шуршит?\n\nЛета показала сухие семена.\n\nШ-ш-ш.\n\n— Классно, — сказал крот. — А у моего корабля мачта всё время падает.\n\nОни помогли друг другу.\n\nЛета всё ещё иногда сравнивала свои работы с чужими. Но теперь у неё появлялся второй вопрос:\n\n«А что особенного есть в моей?»","question":"Бывало ли у тебя, что чужая вещь или умение казались лучше твоих? Что в твоём тогда всё-таки было особенного?","image":"assets/images/stories/sad-kotoryy-zvuchal-korotkaya.webp","audio":"","published":true},{"id":"3-7-07-dlinnaya","topicId":"3-7-07","slug":"chetvyortaya-bashnya-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Меня не взяли в игру","version":"Длинная","duration":"10–15 минут","title":"Четвёртая башня","hero":"ёжик Янки","teaser":"Ёжик Янки приходит к большой игре про драконов, но слышит, что все роли заняты, и придумывает собственную часть приключения.","text":"Во дворе старого дуба дети играли в Королевство драконов.\n\nБелка была королевой.\n\nЗаяц — рыцарем.\n\nДва мышонка — драконами.\n\nКрот охранял сокровища.\n\nЁжик Янки подошёл с деревянным мечом.\n\n— Я тоже буду рыцарем!\n\nЗаяц покачал головой:\n\n— Рыцарь уже есть.\n\n— Тогда драконом.\n\n— Драконов уже два.\n\n— Тогда сокровищем.\n\nМышонок засмеялся:\n\n— Сокровище не бегает.\n\nВсе снова побежали к башне из коробок.\n\nЯнки остался у забора.\n\nЕму стало жарко в ушах.\n\nОн хотел крикнуть: «Тогда я вообще с вами никогда играть не буду!»\n\nНо не крикнул.\n\nОн отошёл к песочнице и ткнул мечом в землю.\n\nПод лавкой лежал кусок старого картона.\n\nЯнки поднял его.\n\nНа картоне была синяя линия от фломастера.\n\nОна напоминала реку.\n\nЯнки дорисовал горы, мост и лес.\n\nВ углу написал значок крестиком.\n\n— Тут будет тайный вход, — решил он.\n\nОн нашёл три шишки — это стали каменные великаны.\n\nПалочка превратилась в мост.\n\nА большая перевёрнутая корзина — в четвёртую башню, которой не было в игре у дуба.\n\nЯнки так увлёкся картой, что не заметил, как рядом остановилась девочка-крольчонок.\n\n— Что это?\n\n— Карта Северной земли.\n\n— А где Северная земля?\n\nЯнки показал на песочницу.\n\n— Тут.\n\n— Можно я буду путешественницей?\n\nЯнки на секунду замолчал.\n\nОн вспомнил, как неприятно было услышать «все роли заняты».\n\n— Можно. Но тебе нужна сумка.\n\nОни сделали сумку из листа лопуха и начали искать тайный вход.\n\nВ это время у дуба раздался громкий спор.\n\n— Дракон украл сокровища!\n\n— Неправда, рыцарь сам их потерял!\n\n— Королева сказала спрятать!\n\nИгра остановилась.\n\nОдин мышонок увидел карту Янки.\n\n— Что у вас?\n\nКрольчонок важно ответила:\n\n— Мы идём в четвёртую башню.\n\n— Какую ещё башню?\n\n— Ту, которую никто не нашёл.\n\nМышонок подошёл ближе.\n\nЗа ним — второй дракон.\n\nПотом королева.\n\nЯнки почувствовал, как внутри снова всё сжалось. Сейчас они заберут карту и будут играть без него.\n\nКоролева спросила:\n\n— А в нашей игре может быть четвёртая башня?\n\nЯнки посмотрел на карту.\n\n— Может. Но там есть мост, который открывается только картографом.\n\n— А кто картограф?\n\n— Я.\n\nЗаяц-рыцарь хотел сказать что-то, но королева уже спросила:\n\n— Тогда покажешь дорогу?\n\nЯнки кивнул.\n\nТеперь все пошли за ним к песочнице.\n\nПо правилам Янки через «реку» нельзя было просто перепрыгнуть. Нужно было найти три камня. Драконы должны были не нападать, а нести один камень вместе. Рыцарь отвечал на загадку. Королева искала ключ под шишкой.\n\nИгра стала совсем другой.\n\nНо через некоторое время Янки заметил, что ему стало тесно: все говорили одновременно, карту тянули в разные стороны.\n\n— Стоп, — сказал он. — Карту не рвём. Кто хочет добавить место — говорит мне.\n\n— А я хочу болото! — сказал мышонок.\n\n— Давай здесь.\n\n— А я ледяную гору!\n\n— Тут.\n\nКарта росла.\n\nПод вечер дети снова разбежались по домам.\n\nЗаяц подошёл к Янки:\n\n— Завтра ты будешь рыцарем, если хочешь.\n\nЯнки подумал.\n\nУтром ему очень хотелось именно этой роли.\n\nА теперь?\n\n— Может быть. Но сначала я хочу закончить Северную землю.\n\n— Тогда я могу быть вторым картографом?\n\nЯнки улыбнулся.\n\n— Можно. Только придумай свою башню.\n\nНа следующий день возле дуба было уже пять башен.\n\nА ещё болото, ледяная гора и мост, который открывался только после смешной песни.\n\nИногда в игре действительно не оказывалось места для ещё одного дракона.\n\nНо Янки теперь знал: роли не всегда заканчиваются там, где заканчивается чей-то первый список.\n\nЧерез неделю Янки сам оказался в другой ситуации. Он с крольчонком строил Северную землю, когда к ним подошёл маленький барсучок.\n\n— Можно с вами?\n\nЯнки уже хотел сказать:\n\n— У нас всё придумано.\n\nСлова почти вылетели.\n\nОн вспомнил тот день у дуба.\n\n— Какие игры ты любишь?\n\n— Я люблю искать следы.\n\nВ Северной земле ещё не было следопыта.\n\nБарсучок придумал отпечатки лап, спрятал их между башнями и добавил историю про пропавшего ледяного зверя.\n\nИгра снова изменилась.\n\nНо иногда Янки всё же хотел играть только вдвоём с крольчонком. Тогда он так и говорил:\n\n— Мы сейчас заканчиваем нашу часть. Через десять минут можно присоединиться к новому походу.\n\nОказалось, место в игре можно искать по-разному.\n\nИногда придумать новую роль.\n\nИногда начать свою игру.\n\nА иногда услышать «сейчас нет» — и знать, что это неприятно, но это не значит «с тобой никогда не хотят играть».","question":"Какую новую роль ты бы мог придумать для игры, если привычные роли уже заняты?","image":"assets/images/stories/chetvyortaya-bashnya-dlinnaya.webp","audio":"","published":true},{"id":"3-7-07-korotkaya","topicId":"3-7-07","slug":"chetvyortaya-bashnya-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Меня не взяли в игру","version":"Короткая","duration":"3–5 минут","title":"Четвёртая башня","hero":"ёжик Янки","teaser":"Ёжик Янки приходит к большой игре про драконов, но слышит, что все роли заняты, и придумывает собственную часть приключения.","text":"Во дворе дети играли в Королевство драконов.\n\nЁжик Янки подошёл:\n\n— Я буду рыцарем!\n\n— Рыцарь уже есть.\n\n— Тогда драконом.\n\n— Драконов уже два.\n\nЯнки отошёл к песочнице. Ему было очень обидно.\n\nПод лавкой он нашёл картон и нарисовал на нём реку, горы, мост и тайный крестик.\n\n— Здесь будет четвёртая башня.\n\nРядом остановилась девочка-крольчонок.\n\n— А можно я буду путешественницей?\n\nЯнки вспомнил, как неприятно было услышать «роли заняты».\n\n— Можно.\n\nОни отправились искать тайный вход.\n\nВскоре дети из старой игры заметили карту.\n\n— Что это за башня?\n\n— Та, которую никто не нашёл, — ответила путешественница.\n\nКоролева спросила:\n\n— Она может быть в нашем королевстве?\n\n— Может. Но дорогу знает только картограф.\n\n— А кто картограф?\n\n— Я, — сказал Янки.\n\nТеперь все пошли по его карте. Драконы переносили камни, рыцарь отвечал на загадку, а королева искала ключ.\n\nНа карте появилось болото, ледяная гора и ещё одна башня.\n\nВечером заяц сказал:\n\n— Завтра можешь быть рыцарем.\n\nЯнки подумал.\n\n— Может быть. Но сначала я хочу закончить Северную землю.\n\nНа следующий день возле дуба было уже пять башен.\n\nЧерез неделю к Янки подошёл маленький барсучок:\n\n— Можно с вами?\n\nЯнки почти сказал:\n\n— У нас всё занято.\n\nПотом спросил:\n\n— Что ты любишь делать?\n\n— Искать следы.\n\nТак в Северной земле появился следопыт.\n\nИногда Янки всё равно хотел закончить игру только с одним другом. Тогда он говорил об этом прямо и предлагал присоединиться позже.\n\nТеперь он знал: «не сейчас» и «никогда» — не одно и то же.","question":"Какую новую роль ты бы мог придумать для игры, если привычные роли уже заняты?","image":"assets/images/stories/chetvyortaya-bashnya-korotkaya.webp","audio":"","published":true},{"id":"3-7-08-dlinnaya","topicId":"3-7-08","slug":"dva-kapitana-odnoy-lodki-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Поссорился с другом","version":"Длинная","duration":"10–15 минут","title":"Два капитана одной лодки","hero":"выдрёнок Сэм и бобрёнок Кай","teaser":"Два лучших друга ссорятся из-за того, куда должна плыть их лодка, и неожиданная остановка среди камышей заставляет их снова действовать вместе.","text":"Выдрёнок Сэм и бобрёнок Кай построили лодку из большого куска коры.\n\nСэм сделал парус.\n\nКай — маленький руль.\n\nНа борту они нарисовали волны и написали: «Два капитана».\n\nВ день первого плавания Сэм принёс карту.\n\n— Сначала плывём к острову Лягушек.\n\nКай покачал головой.\n\n— Нет. Сначала к Старому мосту. Там течение быстрее.\n\n— Но я нарисовал маршрут.\n\n— А я сделал руль.\n\n— И что?\n\n— А то, что капитан решает, куда плыть.\n\n— Тут два капитана!\n\n— Тогда сегодня я первый.\n\n— Почему это ты?\n\nЧерез минуту они уже говорили громче, чем плескалась река.\n\nСэм схватил парус.\n\nКай — руль.\n\n— Отдай!\n\n— Сам отдай!\n\nЛодка повернулась боком.\n\nПорыв ветра надул парус.\n\nФью!\n\nЛодку понесло прямо в камыши.\n\nШурх!\n\nОна застряла между двумя кочками.\n\nСэм сел на один край.\n\nКай — на другой.\n\n— Из-за тебя.\n\n— Нет, из-за тебя.\n\nОни молчали.\n\nРядом квакнула лягушка.\n\nКва.\n\nПотом ещё раз.\n\nКва.\n\nВода тихо качала лодку.\n\nЧерез некоторое время Кай попробовал повернуть руль. Он упёрся в камыш.\n\nСэм потянул парус. Ветер толкнул лодку ещё глубже.\n\n— Не трогай мой парус, — сказал Сэм.\n\n— Я и не хочу.\n\nСнова тишина.\n\nПотом Сэм заметил, что вода начинает медленно прибывать в лодку через маленькую щель.\n\n— Эм…\n\nКай тоже увидел.\n\n— Нужно выбраться.\n\nОни посмотрели друг на друга.\n\nСсориться можно было потом. А сейчас лодка сидела в камышах.\n\n— Я могу подтянуть парус, чтобы ветер не толкал, — сказал Сэм.\n\n— А я попробую оттолкнуться веслом.\n\nСэм свернул парус.\n\nКай упёр весло в дно.\n\nРаз.\n\nЛодка качнулась.\n\nДва.\n\nШурх!\n\nКамыш отпустил один край.\n\n— Ещё!\n\nТри.\n\nЛодка выскочила на чистую воду.\n\nОба засмеялись от неожиданности.\n\nПотом снова вспомнили, что сердятся, и замолчали.\n\nКай первым сказал:\n\n— Я правда хотел к мосту. Я весь вечер думал про течение.\n\nСэм провёл лапой по своей карте.\n\n— А я весь вечер рисовал остров. И когда ты сказал «нет», мне показалось, что карта тебе вообще не нужна.\n\n— Нужна. Просто я тоже хотел решать.\n\nСэм кивнул.\n\n— Я тоже.\n\nОни посмотрели на надпись «Два капитана».\n\n— Плохое название? — спросил Кай.\n\n— Нет. Просто для двух капитанов нужны два голоса.\n\nОни придумали правило: каждый выбирает по одной точке маршрута, а между ними путь решают вместе.\n\nСначала — остров Лягушек.\n\nПотом — Старый мост.\n\nНа острове они нашли огромный лист кувшинки и устроили перекус.\n\nУ моста течение оказалось и правда быстрым. Кай показал, как держать руль, а Сэм — как повернуть парус.\n\nКогда солнце стало садиться, они вернулись домой.\n\nУ причала Кай заметил царапину на борту.\n\n— Это камыши.\n\nСэм потрогал её.\n\n— Оставим?\n\n— Зачем?\n\n— Чтобы помнить наше первое плавание.\n\nКай подумал.\n\n— Тогда рядом нарисуем два весла.\n\nОни нарисовали.\n\nНа следующий день Сэм и Кай снова поссорились — теперь из-за того, какой бутерброд брать в дорогу.\n\nНо на этот раз Сэм сказал:\n\n— Похоже, мы опять в камышах.\n\nКай фыркнул.\n\nПотом засмеялся.\n\nИ они начали говорить.\n\nЧерез несколько дней Сэм и Кай снова были на реке. На этот раз спор начался из-за того, кому держать новый бинокль.\n\n— Ты уже смотрел!\n\n— А ты дольше!\n\nГолоса снова стали громкими.\n\nСэм вдруг посмотрел на камыши.\n\nКай тоже.\n\n— Мы опять туда плывём, — сказал он.\n\nОни рассмеялись не сразу. Сначала оба ещё сердились.\n\nПотом Сэм предложил:\n\n— Две минуты ты, две я. Таймер на часах.\n\n— И если увидим что-то важное, показываем сразу.\n\nДоговорились.\n\nЧерез минуту Кай заметил цаплю и молча протянул бинокль Сэму, хотя его время ещё не закончилось.\n\nСсоры у друзей не исчезли.\n\nЗато у них появилось название для момента, когда спор уже перестаёт быть про бинокль, карту или бутерброд и начинает тащить их в заросли.\n\n— Камыши, — говорил кто-нибудь.\n\nИ это часто помогало вспомнить, что по одну сторону лодки сидит не противник, а второй капитан.","question":"Что помогает тебе снова начать разговаривать после ссоры?","image":"assets/images/stories/dva-kapitana-odnoy-lodki-dlinnaya.webp","audio":"","published":true},{"id":"3-7-08-korotkaya","topicId":"3-7-08","slug":"dva-kapitana-odnoy-lodki-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Поссорился с другом","version":"Короткая","duration":"3–5 минут","title":"Два капитана одной лодки","hero":"выдрёнок Сэм и бобрёнок Кай","teaser":"Два лучших друга ссорятся из-за того, куда должна плыть их лодка, и неожиданная остановка среди камышей заставляет их снова действовать вместе.","text":"Выдрёнок Сэм и бобрёнок Кай построили лодку.\n\nСэм сделал парус.\n\nКай — руль.\n\nНа борту написали: «Два капитана».\n\nПеред первым плаванием Сэм сказал:\n\n— Плывём к острову Лягушек.\n\n— Нет, к Старому мосту, — ответил Кай.\n\n— Я нарисовал карту!\n\n— А я сделал руль!\n\nОни начали тянуть парус и руль каждый к себе.\n\nФью!\n\nВетер подхватил лодку.\n\nШурх!\n\nОна застряла в камышах.\n\n— Из-за тебя!\n\n— Нет, из-за тебя!\n\nОни сели на разные края и замолчали.\n\nНо лодка застряла крепко.\n\n— Я сверну парус, — наконец сказал Сэм.\n\n— А я оттолкнусь веслом, — ответил Кай.\n\nРаз.\n\nДва.\n\nТри!\n\nЛодка выскочила на чистую воду.\n\nПосле этого Сэм сказал:\n\n— Когда ты отказался плыть по моей карте, мне показалось, что она тебе не нужна.\n\n— Нужна. Я просто тоже хотел решать.\n\nОни придумали: один выбирает первую остановку, другой — вторую.\n\nСначала поплыли к острову Лягушек, потом к Старому мосту.\n\nНа борту осталась маленькая царапина от камышей.\n\nСэм предложил не закрашивать её.\n\n— Пусть напоминает про наше первое плавание.\n\nКай рядом нарисовал два весла.\n\nЧерез несколько дней друзья снова заспорили — теперь из-за бинокля.\n\n— Ты дольше смотрел!\n\n— Нет, ты!\n\nСэм взглянул на камыши.\n\n— Кажется, мы опять туда плывём.\n\nКай фыркнул.\n\nОни всё ещё сердились, но смогли договориться: по две минуты каждому.\n\nПозже слово «камыши» стало их смешным сигналом. Оно напоминало: спор есть спор, а в лодке всё равно сидят два друга.","question":"Что помогает тебе снова начать разговаривать после ссоры?","image":"assets/images/stories/dva-kapitana-odnoy-lodki-korotkaya.webp","audio":"","published":true},{"id":"3-7-09-dlinnaya","topicId":"3-7-09","slug":"knopka-privet-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Стесняюсь знакомиться","version":"Длинная","duration":"10–15 минут","title":"Кнопка «Привет»","hero":"маленький робот Тико","teaser":"У робота Тико слова застревают именно тогда, когда нужно познакомиться, и он находит свой маленький способ начать разговор.","text":"Маленький робот Тико умел многое.\n\nОн умел считать винтики.\n\nУмел складывать бумажные самолёты.\n\nУмел отличать мяту от базилика по запаху.\n\nНо когда нужно было подойти к незнакомому ребёнку и сказать «Привет», внутри у Тико будто нажималась кнопка «Стоп».\n\nВ этот день он пришёл в Клуб маленьких изобретателей.\n\nВ комнате уже собирали машины из коробок, запускали бумажные вертолёты и выращивали фасоль в прозрачных стаканчиках.\n\nТико увидел мальчика, который делал механическую гусеницу.\n\n«Скажу: “Привет, как тебя зовут?”»\n\nТико подошёл.\n\nМальчик поднял голову.\n\nТико открыл рот.\n\n— П… п…\n\nВнутри будто загудел вентилятор.\n\nЖ-ж-ж.\n\n— Тебе что-то нужно? — спросил мальчик.\n\nТико покачал головой и отошёл.\n\n«Не умею знакомиться».\n\nОн сел у стола с растениями.\n\nВ одном стаканчике росла фасоль. На табличке было написано: «Меня зовут Боб. Поздоровайся со мной».\n\nТико посмотрел на росток.\n\n— Привет, Боб.\n\nНичего не застряло.\n\n— Как у тебя дела?\n\nРосток молчал.\n\n— Понятно. У меня тоже немного странный день.\n\nРядом засмеялась девочка с зелёными заколками.\n\n— Ты разговариваешь с фасолью?\n\nТико снова почувствовал кнопку «Стоп».\n\nНо девочка смотрела не сердито.\n\nТико кивнул.\n\n— Её зовут Боб.\n\n— Хорошее имя. Я Мия.\n\nТико не успел подготовить правильную фразу.\n\n— Я Тико.\n\nИ вдруг заметил: знакомство уже случилось.\n\nМия показала ему бумажный вертолёт.\n\n— Он всё время падает боком.\n\nТико взял его и увидел, что одна лопасть короче.\n\n— Можно я покажу?\n\n— Конечно.\n\nОни подрезали вторую лопасть.\n\nВертолёт закрутился ровнее.\n\nПозже Тико снова увидел мальчика с механической гусеницей.\n\nТеперь он знал его имя — Арсен, потому что услышал, как к нему обращалась ведущая.\n\nТико хотел спросить про гусеницу.\n\nКнопка «Стоп» снова была рядом.\n\nОн не заставлял себя произносить целую красивую фразу.\n\nПросто показал на гусеницу:\n\n— Она сама поворачивает?\n\nАрсен оживился.\n\n— Да! Смотри.\n\nОн нажал рычажок.\n\nГусеница повернула.\n\n— А у тебя что?\n\nТико показал бумажный вертолёт.\n\nЧерез десять минут они уже спорили, можно ли приделать гусенице пропеллер.\n\nВ конце занятия ведущая предложила всем встать в круг и назвать своё имя.\n\nКогда очередь дошла до Тико, ему снова стало неловко.\n\nНо теперь в комнате уже были Мия, Арсен и даже фасоль Боб.\n\n— Я Тико, — сказал он.\n\nПотом подумал и добавил:\n\n— Я люблю чинить то, что падает боком.\n\nМия засмеялась.\n\nПосле клуба Тико нарисовал на своём блокноте маленькую зелёную кнопку.\n\nНа ней написал: «Привет».\n\nНо кнопка была не для того, чтобы обязательно нажать и сразу заговорить.\n\nРядом он нарисовал ещё три:\n\n«Показать».\n\n«Спросить».\n\n«Сделать рядом».\n\nВ следующий раз, когда слова застряли, Тико мог выбрать любую.\n\nИногда знакомство начиналось с «Привет».\n\nА иногда — с вопроса о гусенице.\n\nИ это тоже работало.\n\nНа следующем занятии в клуб пришла новая девочка. Она стояла у двери и не подходила ни к одному столу.\n\nТико заметил, что она всё время поправляет ремешок рюкзака — почти так же, как он сам крутил винтик на пальце, когда волновался.\n\nОн не стал говорить:\n\n«Не стесняйся».\n\nВместо этого показал на свободный стул рядом:\n\n— Я собираю мост. Тут нужна ещё одна деталь. Хочешь выбрать?\n\nДевочка кивнула.\n\nЧерез несколько минут они уже спорили, какой мост прочнее — треугольный или квадратный.\n\n— Кстати, я Тико.\n\n— А я Лана.\n\nТико посмотрел на свои нарисованные кнопки.\n\nВ этот раз он выбрал «сделать рядом».\n\nИ ему понравилось, что иногда маленький способ познакомиться можно не только придумать для себя, но и предложить другому.","question":"Как тебе было бы легче познакомиться: сказать «привет», показать игрушку, задать вопрос или придумать свой способ?","image":"assets/images/stories/knopka-privet-dlinnaya.webp","audio":"","published":true},{"id":"3-7-09-korotkaya","topicId":"3-7-09","slug":"knopka-privet-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Стесняюсь знакомиться","version":"Короткая","duration":"3–5 минут","title":"Кнопка «Привет»","hero":"маленький робот Тико","teaser":"У робота Тико слова застревают именно тогда, когда нужно познакомиться, и он находит свой маленький способ начать разговор.","text":"Робот Тико умел считать винтики, складывать самолёты и выращивать фасоль.\n\nНо знакомиться он стеснялся.\n\nВ Клубе изобретателей Тико увидел мальчика с механической гусеницей.\n\n«Скажу: “Привет!”»\n\nОн подошёл.\n\n— П… п…\n\nСлова застряли.\n\nТико отошёл к столу с растениями.\n\nТам росла фасоль с табличкой: «Меня зовут Боб».\n\n— Привет, Боб, — тихо сказал Тико.\n\n— Ты разговариваешь с фасолью? — спросила девочка рядом.\n\nТико кивнул.\n\n— Её зовут Боб.\n\n— А я Мия.\n\n— Я Тико.\n\nТико удивился: знакомство уже произошло.\n\nПозже он снова подошёл к мальчику с гусеницей. На этот раз не пытался сказать длинную фразу.\n\nПросто спросил:\n\n— Она сама поворачивает?\n\n— Да! Смотри!\n\nЧерез минуту они уже обсуждали, можно ли приделать гусенице пропеллер.\n\nДома Тико нарисовал четыре маленькие кнопки:\n\n«Привет».\n\n«Показать».\n\n«Спросить».\n\n«Сделать рядом».\n\nТеперь он знал: чтобы познакомиться, не обязательно начинать идеально.\n\nИногда достаточно одного маленького вопроса.\n\nНа следующем занятии Тико увидел новую девочку, которая стояла одна у двери.\n\nОн не стал заставлять её говорить.\n\nПросто показал на свободный стул:\n\n— Я строю мост. Хочешь выбрать деталь?\n\nОна кивнула.\n\nЧерез несколько минут они уже вместе проверяли мост.\n\n— Кстати, я Тико.\n\n— А я Лана.\n\nВ этот раз Тико выбрал кнопку «сделать рядом».\n\nОказалось, знакомство иногда начинается даже без слова «привет».","question":"Как тебе было бы легче познакомиться: сказать «привет», показать игрушку, задать вопрос или придумать свой способ?","image":"assets/images/stories/knopka-privet-korotkaya.webp","audio":"","published":true},{"id":"3-7-10-dlinnaya","topicId":"3-7-10","slug":"sinyaya-dver-doktora-lapy-dlinnaya","age":"3–7 лет","ageKey":"3-7","theme":"Боюсь врача","version":"Длинная","duration":"10–15 минут","title":"Синяя дверь доктора Лапы","hero":"щенок Рой","teaser":"Щенок Рой боится кабинета врача, но возможность заранее узнать, что будет происходить, помогает ему пройти осмотр шаг за шагом.","text":"У щенка Роя заболело ухо.\n\nНе сильно. Но неприятно.\n\nОн тряс головой:\n\nшлёп-шлёп,\n\nчесал ухо лапой и сердился.\n\nМама сказала:\n\n— Завтра сходим к доктору.\n\nРой сразу перестал чесаться.\n\n— Не пойду.\n\n— Ухо мешает.\n\n— Пусть мешает.\n\nВ прошлый раз он видел в коридоре белые халаты, блестящие инструменты и слышал, как за дверью кто-то громко плакал.\n\nС тех пор слово «доктор» казалось Рою огромным.\n\nНа следующий день они пришли в клинику.\n\nКабинет был за синей дверью.\n\nРой вцепился лапами в скамейку.\n\n— Я не зайду.\n\nМама села рядом.\n\n— Мы можем сначала посидеть здесь.\n\nЧерез некоторое время синяя дверь открылась.\n\nВышла доктор Лапа — большая спокойная собака в зелёном халате.\n\nОна не подошла сразу к Рою.\n\n— Привет. Я доктор Лапа. Твоё ухо сегодня главный гость?\n\nРой спрятал ухо.\n\n— Нет.\n\n— Понятно. Тогда пока главный гость — твой игрушечный динозавр?\n\nРой держал маленького динозавра.\n\n— Его зовут Хрум.\n\n— Хрум согласен зайти первым?\n\nРой посмотрел на маму.\n\nПотом на синюю дверь.\n\n— Только Хрум.\n\nВ кабинете доктор посадила динозавра на стул.\n\n— Сначала я обычно спрашиваю, что случилось. Потом смотрю. Иногда слушаю. Иногда нужно сделать что-то ещё, и тогда я заранее рассказываю.\n\nОна показала маленький фонарик.\n\n— Это для уха. Он светит.\n\nДоктор посветила на лапу Роя.\n\nКружок света.\n\n— Не горячо, — сказал Рой.\n\n— Верно.\n\nОна показала прибор с круглой воронкой.\n\n— Эту часть я поднесу к уху. Она не должна больно давить. Если тебе станет неприятно, скажи «стоп» или подними лапу.\n\n— А если я скажу?\n\n— Я остановлюсь и мы решим, что дальше.\n\nДоктор сначала осмотрела ухо Хрума.\n\n— У динозавра в ухе… пластмасса.\n\nРой фыркнул.\n\nПотом доктор спросила:\n\n— Можно посмотреть твоё здоровое ухо? Только на секунду.\n\nРой подумал.\n\n— Здоровое можно.\n\nДоктор поднесла прибор.\n\n— Один… два… готово.\n\nРой моргнул.\n\n— Всё?\n\n— Это ухо — всё.\n\n— А больное?\n\n— Там может быть неприятнее, потому что оно чувствительное. Я буду очень медленно.\n\nРой сел на мамины колени.\n\n— Сначала просто фонарик.\n\nСвет.\n\n— Теперь прибор.\n\nРой сжал Хрума.\n\nДоктор поднесла прибор.\n\nВ ухе стало немного неприятно.\n\nРой поднял лапу.\n\nДоктор сразу убрала прибор.\n\n— Стоп.\n\nРой удивился.\n\n— Я ещё не всё увидела. Хочешь минутку или попробуем, когда будешь готов?\n\nРой подышал. Погладил динозавра.\n\n— Ещё раз. Только быстро.\n\n— Я постараюсь сделать коротко, но если не успею, скажу.\n\nВторой раз доктор посмотрела чуть дольше.\n\n— Готово.\n\nОна объяснила маме, что ухо раздражено и как за ним ухаживать. Потом показала капли.\n\nРой насторожился.\n\n— Это больно?\n\n— Может немного щипнуть. Я не могу обещать, что ты ничего не почувствуешь. Но мама будет рядом, а мы можем сначала потрогать каплю пальцем.\n\nРой коснулся капли.\n\nХолодная.\n\nДома мама закапала ухо. Рой поморщился.\n\n— Щиплет.\n\n— Я рядом, — сказала мама.\n\nЧерез несколько дней ухо перестало беспокоить.\n\nПроходя мимо клиники, Рой посмотрел на синюю дверь.\n\nОна всё ещё была дверью к доктору. Рой не решил вдруг, что врачи — его любимое развлечение.\n\nНо теперь за синей дверью он представлял не неизвестность.\n\nОн вспоминал фонарик.\n\n«Один… два… готово».\n\nИ слово «стоп», которое доктор услышала.\n\nЧерез месяц Рою понадобилась прививка. Услышав слово, он снова напрягся.\n\nНа этот раз он уже знал, что спросить.\n\n— Что будет сначала?\n\nМедсестра объяснила порядок.\n\n— А можно я не буду смотреть?\n\n— Можно.\n\n— А мама будет рядом?\n\n— Да.\n\n— А если будет больно?\n\n— Укол может коротко заболеть. Потом место может ныть.\n\nРой не обрадовался этим ответам. Но ему понравилось, что никто не притворяется, будто он ничего не почувствует.\n\nПеред уколом он выбрал смотреть на наклейку с китом на стене и сжимать Хрума.\n\nБыстро кольнуло.\n\nРой поморщился.\n\n— Ай.\n\n— Готово, — сказала медсестра.\n\nПо дороге домой он не рассказывал всем, что «совсем не боялся».\n\nОн боялся.\n\nПросто теперь у страха были вопросы, ответы, возможность остановиться во время осмотра и взрослые рядом.\n\nИ от этого он занимал в голове уже не весь кабинет.","question":"Что тебе хотелось бы заранее узнать или спросить у врача перед осмотром?","image":"assets/images/stories/sinyaya-dver-doktora-lapy-dlinnaya.webp","audio":"","published":true},{"id":"3-7-10-korotkaya","topicId":"3-7-10","slug":"sinyaya-dver-doktora-lapy-korotkaya","age":"3–7 лет","ageKey":"3-7","theme":"Боюсь врача","version":"Короткая","duration":"3–5 минут","title":"Синяя дверь доктора Лапы","hero":"щенок Рой","teaser":"Щенок Рой боится кабинета врача, но возможность заранее узнать, что будет происходить, помогает ему пройти осмотр шаг за шагом.","text":"У щенка Роя заболело ухо.\n\nМама сказала:\n\n— Сходим к доктору.\n\n— Не пойду, — ответил Рой.\n\nВ клинике кабинет был за синей дверью.\n\nРой сел на скамейку и не хотел заходить.\n\nДоктор Лапа вышла сама.\n\n— Может, сначала осмотрим твоего динозавра?\n\n— Его зовут Хрум, — сказал Рой.\n\nВ кабинете доктор показала маленький фонарик.\n\n— Он просто светит.\n\nПотом показала прибор для уха.\n\n— Если станет неприятно, скажи «стоп» или подними лапу.\n\nСначала доктор посмотрела здоровое ухо.\n\n— Один… два… готово.\n\nПотом больное.\n\nРой сжал динозавра.\n\nСтало неприятно, и он поднял лапу.\n\nДоктор сразу остановилась.\n\n— Хочешь минутку?\n\nРой немного посидел.\n\n— Теперь можно ещё раз.\n\nДоктор закончила осмотр и рассказала маме, что делать дома.\n\nУ двери Рой снова посмотрел на кабинет.\n\nОн всё ещё не любил ходить к врачу.\n\nНо теперь знал, что можно спрашивать, что будет происходить, и говорить, если нужно остановиться.\n\nЧерез месяц Рою понадобилась прививка.\n\nОн снова испугался, но уже спросил:\n\n— Что будет сначала? Можно не смотреть? Мама будет рядом?\n\nМедсестра честно сказала, что укол может коротко заболеть.\n\nРой выбрал смотреть на наклейку с китом и держать Хрума.\n\nКольнуло.\n\n— Ай.\n\n— Готово.\n\nРой не говорил, что совсем не боялся.\n\nБоялся.\n\nНо теперь он знал: можно заранее спрашивать, что будет происходить, и не оставаться со страхом один на один.","question":"Что тебе хотелось бы заранее узнать или спросить у врача перед осмотром?","image":"assets/images/stories/sinyaya-dver-doktora-lapy-korotkaya.webp","audio":"","published":true},{"id":"7-9-01-dlinnaya","topicId":"7-9-01","slug":"chetyre-pustyh-kletki-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Боюсь контрольной","version":"Длинная","duration":"10–15 минут","title":"Четыре пустых клетки","hero":"Лея","teaser":"Перед контрольной Лее кажется, что все знания исчезли, но четыре пустых клетки на листе превращаются из угрозы в маршрут, по которому можно двигаться.","text":"В понедельник учительница сказала:\n\n— В пятницу будет небольшая контрольная по математике.\n\nСлово «небольшая» почему-то совсем не помогло Лее.\n\nВесь понедельник она представляла белый лист. Во вторник — красные исправления. В среду ей приснилось, что контрольная состоит из одной задачи длиной до самого пола.\n\nЛея готовилась. Решала примеры. Повторяла таблицу. Вместе с папой разобрала задачи, в которых нужно было узнать время и расстояние.\n\nДома всё получалось.\n\nНо в пятницу утром у школьной двери Лея вдруг подумала:\n\n«А если я сяду — и ничего не вспомню?»\n\nЭта мысль прицепилась к ней, как репей.\n\nНа первом уроке учительница раздала листы.\n\nШурх.\n\nЛея перевернула свой.\n\nПервое задание она знала.\n\nНо глаза уже побежали дальше.\n\nВо втором была задача с поездом.\n\nВ третьем — четыре пустых клетки для ответа.\n\nВ четвёртом — длинное выражение.\n\nЛея посмотрела сразу на всё.\n\nВ голове стало бело.\n\n«Вот. Я же знала. Ничего не помню».\n\nОна взяла карандаш. Пальцы стали холодными.\n\nСосед уже что-то писал.\n\nСзади шелестели страницы.\n\nЧасы на стене тикали слишком громко:\n\nтик.\n\nтик.\n\nтик.\n\nЛее показалось, что каждый звук говорит: «Быстрее».\n\nОна поставила карандаш.\n\nНа полях листа учительница заранее напечатала маленькую фразу: «Начни с того, что видишь».\n\nЛея прочитала её дважды.\n\n«Что я вижу?»\n\nОна закрыла ладонью остальные задания и оставила только первое.\n\n7 × 4.\n\nЭто она знала.\n\n28.\n\nЛея написала ответ.\n\nВ голове ничего волшебного не произошло. Страх не исчез. Но теперь на листе было не всё пусто.\n\nОна открыла второе задание.\n\nПоезд проехал 30 километров утром и ещё 20 после обеда.\n\n«Это просто сложение».\n\n50.\n\nТретье задание было тем самым — с четырьмя пустыми клетками.\n\nНужно было записать числа по порядку после 396.\n\nЛея неожиданно усмехнулась.\n\nОна всю неделю боялась этих пустых клеток, хотя даже не знала, что в них будет.\n\n397.\n\n398.\n\n399.\n\n400.\n\nКлетки заполнились.\n\nА вот четвёртое задание действительно оказалось сложным. Лея начала считать, запуталась и получила число, которое казалось странным.\n\nОна стёрла.\n\nПопробовала снова.\n\nОпять не сходилось.\n\nТревога вернулась.\n\n«Сейчас потрачу всё время!»\n\nЛея поставила рядом маленькую точку и перешла дальше.\n\nТак папа делал, когда собирал мебель: если один винт не поддавался, он не разбирал весь шкаф, а временно переходил к другой части.\n\nК концу контрольной Лея вернулась к сложному выражению.\n\nТеперь заметила, что в первый раз пропустила скобки.\n\n— Осталось пять минут, — сказала учительница.\n\nЛея решила ещё раз.\n\nПолучилось.\n\nКогда листы собрали, она выдохнула так, будто только что долго держала воздух.\n\nНа перемене подруга спросила:\n\n— Ты всё сделала?\n\n— Почти. В одном месте два раза ошиблась.\n\n— Я тоже.\n\nЛея удивилась. Ей казалось, что вокруг все пишут уверенно и только она сидит с холодными руками.\n\nПосле уроков она всё равно переживала из-за оценки.\n\nВ понедельник учительница вернула работы.\n\nУ Леи была одна ошибка — в задаче с дробями, которую они проходили недавно.\n\nРаньше Лея бы сначала увидела именно её.\n\nНо теперь взгляд упал на четыре клетки.\n\n397, 398, 399, 400.\n\nОна вспомнила пятничное утро и то, как страшно было смотреть на них пустыми.\n\nУчительница подошла.\n\n— Хочешь разобрать ошибку?\n\nЛея кивнула.\n\nОни посмотрели задачу. Оказалось, Лея правильно начала, но в конце перепутала два числа.\n\n— Я дома знала, — сказала Лея.\n\n— На контрольной бывает труднее думать, когда волнуешься.\n\n— А как сделать, чтобы вообще не волноваться?\n\nУчительница улыбнулась:\n\n— Я не умею выключать волнение кнопкой. Но можно делать так, чтобы оно не управляло всем листом.\n\nЛея рассказала, как закрыла рукой остальные задания.\n\n— Хороший ход.\n\nВ следующую пятницу никакой контрольной не было. Но на уроке раздали самостоятельную работу.\n\nЛея снова почувствовала знакомый холодок.\n\nНе такой сильный, но знакомый.\n\nОна посмотрела на весь лист.\n\nПотом взяла чистый кусочек бумаги и прикрыла нижнюю половину.\n\nПеред ней осталось одно задание.\n\nТолько одно.\n\nИ с него можно было начать.\n\nЧерез две недели была контрольная по русскому. Лея снова готовилась и снова почувствовала знакомый комок в животе.\n\nНа этот раз она заранее положила рядом маленький листок для черновика. В верхнем углу написала три слова:\n\n«Одно задание».\n\nКонтрольная началась. Первое упражнение оказалось простым. Во втором она сомневалась, как пишется слово. Раньше Лея могла бы сидеть над ним пять минут, пока тревога не разрастётся.\n\nТеперь она поставила возле слова маленький знак вопроса и пошла дальше.\n\nВ конце вернулась и вспомнила правило.\n\nПосле урока Лея рассказала учительнице, что всё равно переживала.\n\n— Я думала, если нашла способ, страх больше не должен появляться.\n\n— Способ нужен не для того, чтобы никогда не волноваться, — ответила учительница. — А чтобы знать, что делать, когда волнение пришло.\n\nЛее эта мысль понравилась больше.\n\nОна не могла заранее знать, какие будут задания.\n\nНо могла знать первый шаг.\n\nОткрыть лист.\n\nНайти то, что понятно.\n\nСделать одну вещь.\n\nА потом следующую.","question":"Что обычно происходит с твоими мыслями, когда ты сильно волнуешься перед важным заданием?","image":"assets/images/stories/chetyre-pustyh-kletki-dlinnaya.webp","audio":"","published":true},{"id":"7-9-01-korotkaya","topicId":"7-9-01","slug":"chetyre-pustyh-kletki-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Боюсь контрольной","version":"Короткая","duration":"3–5 минут","title":"Четыре пустых клетки","hero":"Лея","teaser":"Перед контрольной Лее кажется, что все знания исчезли, но четыре пустых клетки на листе превращаются из угрозы в маршрут, по которому можно двигаться.","text":"В пятницу у Леи была контрольная по математике.\n\nОна готовилась всю неделю, но утром подумала:\n\n«А если я сяду и ничего не вспомню?»\n\nУчительница раздала листы.\n\nЛея увидела задачу с поездом, длинное выражение и четыре пустых клетки.\n\nВ голове стало бело.\n\nСосед уже писал.\n\nЧасы тикали:\n\nтик.\n\nтик.\n\nтик.\n\nНа полях листа было напечатано: «Начни с того, что видишь».\n\nЛея закрыла ладонью остальные задания.\n\nПеред ней осталось только первое.\n\n7 × 4.\n\n28.\n\nОна написала ответ.\n\nПотом решила задачу с поездом.\n\nА четыре страшные пустые клетки оказались совсем простыми: нужно было продолжить ряд после 396.\n\n397.\n\n398.\n\n399.\n\n400.\n\nОдно сложное выражение не получалось. Лея поставила рядом точку и пошла дальше, а в конце вернулась и заметила пропущенные скобки.\n\nКогда контрольная закончилась, страх не исчез волшебным образом. Но лист уже не казался огромным.\n\nВ понедельник Лея получила работу назад. Там была одна ошибка.\n\nОна сначала посмотрела не на неё, а на четыре заполненные клетки.\n\nВ следующий раз, когда перед ней снова оказался длинный лист заданий, Лея прикрыла нижнюю половину чистой бумагой.\n\nПеред ней осталось одно задание.\n\nС него и можно было начать.\n\nЧерез две недели была другая контрольная.\n\nЛея снова волновалась. На черновике она написала:\n\n«Одно задание».\n\nЕсли встречалось сложное место, она ставила маленький знак вопроса и шла дальше, а потом возвращалась.\n\nПосле урока Лея сказала учительнице:\n\n— Я всё равно боялась.\n\n— Способ не обязан выключать страх, — ответила та. — Он помогает знать, что делать рядом с ним.\n\nЛея запомнила это.\n\nОна не знала заранее все ответы.\n\nЗато знала, с чего начать.","question":"Что обычно происходит с твоими мыслями, когда ты сильно волнуешься перед важным заданием?","image":"assets/images/stories/chetyre-pustyh-kletki-korotkaya.webp","audio":"","published":true},{"id":"7-9-02-dlinnaya","topicId":"7-9-02","slug":"ostrov-kotorogo-ne-bylo-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Ошибся перед всем классом","version":"Длинная","duration":"10–15 минут","title":"Остров, которого не было","hero":"Артём","teaser":"Артём ошибается у доски перед всем классом, но урок о старых картах неожиданно меняет его отношение к одному неловкому моменту.","text":"На уроке географии учительница вывесила большую карту мира.\n\n— Кто покажет, где находится Исландия?\n\nАртём знал.\n\nПо крайней мере, ему казалось, что знал.\n\nОн поднял руку и вышел к доске. В классе было тихо. Двадцать человек смотрели на него, и указка вдруг стала слишком длинной.\n\nАртём ткнул в остров.\n\n— Здесь.\n\nС задней парты кто-то прыснул.\n\nУчительница мягко сказала:\n\n— Посмотри ещё раз.\n\nАртём посмотрел.\n\nОн указал на Ирландию.\n\nЩёки сразу вспыхнули.\n\n— А-а… не туда.\n\nКто-то прошептал:\n\n— Географ.\n\nПара ребят засмеялись.\n\nАртём быстро нашёл Исландию, сел и до конца урока почти не поднимал глаз.\n\nНа перемене ему казалось, что все помнят только эту ошибку.\n\nНа самом деле половина класса уже обсуждала футбол, но Артём слышал в голове одно слово:\n\n«Географ».\n\nПосле уроков он сказал другу:\n\n— Больше к доске не выйду.\n\n— Да ладно, — ответил тот. — Я вчера трижды восемь сказал двадцать четыре.\n\n— Это другое.\n\nАртём не мог объяснить, почему другое. Наверное, потому что чужая ошибка выглядела маленькой, а своя — огромной.\n\nНа следующем уроке учительница принесла старые карты.\n\nНа одной по краям океана были нарисованы морские чудовища.\n\nНа другой там, где сейчас точно знали очертания берега, стояла надпись: «Неизвестная земля».\n\n— Раньше картографы рисовали мир по тому, что знали, — сказала учительница. — Иногда ошибались. Иногда оставляли пустое место. Иногда исправляли карты много лет спустя.\n\nАртём рассматривал карту с огромной рыбой возле края света.\n\n— Они не стеснялись, что нарисовали неправильно? — спросил он.\n\n— Кто-то наверняка стеснялся. Но если бы новые путешественники не исправляли старые карты, у нас были бы очень странные атласы.\n\nВ конце урока каждому дали задание нарисовать «карту неизвестного острова». Нужно было придумать горы, бухты, леса и названия.\n\nАртём назвал свой остров «Не Туда».\n\nСначала просто потому, что сам себя подколол.\n\nПотом решил развить идею.\n\nНа острове была бухта «Ой».\n\nГора «Сейчас исправлю».\n\nРека «Проверю ещё раз».\n\nА в центре — большой маяк «Нашёл».\n\nДруг заглянул через плечо.\n\n— Это про Исландию?\n\nАртём напрягся.\n\n— Ну да.\n\nДруг засмеялся, но не зло.\n\n— Тогда добавь болото «Я был уверен».\n\nАртём тоже рассмеялся.\n\nК концу урока вокруг карты собралось несколько человек. Кто-то предложил лес «Не расслышал вопрос», кто-то — мост «Подсказка».\n\nТот самый мальчик с задней парты, который сказал «географ», подошёл последним.\n\n— Слушай… я тогда зря сказал.\n\nАртём не ожидал.\n\n— Угу.\n\n— Я сам Исландию вообще не нашёл бы.\n\n— Можешь найти на моей карте болото «Я был уверен».\n\nОни оба хмыкнули.\n\nЧерез неделю на уроке снова понадобился доброволец.\n\nУчительница спросила:\n\n— Кто покажет течение Гольфстрим?\n\nАртём почувствовал, как внутри всё сжалось.\n\nРуку он не поднял.\n\nПодняла девочка впереди. Она вышла, показала не в ту сторону и сама сказала:\n\n— Кажется, я поплыла против течения.\n\nКласс засмеялся вместе с ней.\n\nУчительница помогла исправить.\n\nАртём заметил, как быстро всё закончилось.\n\nНа следующем вопросе он всё-таки поднял руку.\n\nНе потому что перестал бояться ошибиться перед классом.\n\nЕму всё ещё не нравилось краснеть у доски.\n\nНо теперь в голове у него была карта.\n\nЕсли ткнул не туда — это ещё не конец урока.\n\nМожно посмотреть ещё раз.\n\nПереставить указку.\n\nИ дорисовать берег там, где минуту назад был несуществующий остров.\n\nЧерез месяц класс готовил стенд «Ошибки, которые двинули дело дальше». Кто-то нашёл историю случайно изобретённого липкого стикера, кто-то — ошибочные научные гипотезы, которые позже пришлось пересматривать.\n\nАртёму досталась история старой карты.\n\nОн вышел к классу с указкой.\n\nНа экране появилась та самая карта с морским чудовищем.\n\n— Здесь картографы не знали, что находится дальше, и рисовали предположения, — начал Артём.\n\nВ этот момент он перепутал две даты.\n\nС первой парты тихо подсказали:\n\n— Не 1512-й, а 1521-й.\n\nРаньше Артём почувствовал бы, как всё падает внутри.\n\nТеперь он посмотрел на слайд.\n\n— Точно. Я только что добавил к докладу свежую ошибку. Исправляю.\n\nКласс усмехнулся — не над ним, а вместе с ним.\n\nДоклад продолжился.\n\nПосле урока Артём понял, что самое неприятное в ошибке у доски иногда длится всего несколько секунд. Остальное время можно снова говорить, думать и двигать указку дальше.","question":"Что тебе хотелось бы услышать от одноклассников или учителя, если ты ошибся перед всеми?","image":"assets/images/stories/ostrov-kotorogo-ne-bylo-dlinnaya.webp","audio":"","published":true},{"id":"7-9-02-korotkaya","topicId":"7-9-02","slug":"ostrov-kotorogo-ne-bylo-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Ошибся перед всем классом","version":"Короткая","duration":"3–5 минут","title":"Остров, которого не было","hero":"Артём","teaser":"Артём ошибается у доски перед всем классом, но урок о старых картах неожиданно меняет его отношение к одному неловкому моменту.","text":"На уроке географии Артём вышел к карте.\n\n— Где Исландия?\n\nОн уверенно ткнул указкой в остров.\n\nС задней парты кто-то прыснул.\n\nАртём посмотрел внимательнее.\n\nЭто была Ирландия.\n\n— Ой.\n\nКто-то прошептал:\n\n— Географ.\n\nАртём быстро исправился и сел с красными щеками.\n\nЕму казалось, что теперь весь класс будет помнить эту ошибку.\n\nНа следующем уроке учительница принесла старые карты. На них были неправильные берега, пустые места и даже морские чудовища.\n\n— Карты менялись, когда люди узнавали больше, — объяснила она.\n\nПотом класс придумывал собственные острова.\n\nАртём назвал свой «Не Туда».\n\nНа нём появились бухта «Ой», гора «Сейчас исправлю» и маяк «Нашёл».\n\nОдноклассники начали добавлять свои названия.\n\nДаже мальчик, который смеялся, подошёл:\n\n— Я тогда зря сказал. Сам бы Исландию не нашёл.\n\nЧерез неделю учительница снова задала вопрос у карты.\n\nАртёму всё ещё было неловко выходить.\n\nНо на следующем вопросе он поднял руку.\n\nЕсли указка окажется не там, где нужно, всегда можно посмотреть ещё раз и передвинуть её.\n\nПозже Артём выступал с докладом о старых картах и сам перепутал две даты.\n\nКто-то тихо подсказал.\n\nАртём замер на секунду, потом сказал:\n\n— Точно. Свежая ошибка для моего доклада. Исправляю.\n\nИ продолжил.\n\nОн всё ещё покраснел.\n\nНо теперь знал: ошибка у доски не обязана становиться всем выступлением. Иногда она занимает несколько секунд, а потом указка снова движется дальше.","question":"Что тебе хотелось бы услышать от одноклассников или учителя, если ты ошибся перед всеми?","image":"assets/images/stories/ostrov-kotorogo-ne-bylo-korotkaya.webp","audio":"","published":true},{"id":"7-9-03-dlinnaya","topicId":"7-9-03","slug":"kurtka-s-planetami-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Меня дразнят","version":"Длинная","duration":"10–15 минут","title":"Куртка с планетами","hero":"Ника","teaser":"Нику дразнят из-за необычной куртки, которую она украсила сама, и ей приходится решать не только что носить, но и кому рассказать о происходящем.","text":"У Ники была тёмно-синяя джинсовая куртка.\n\nНа спине она сама нарисовала Сатурн с кольцами, на рукаве пришила маленький Марс, а возле кармана — крошечную Землю.\n\nКуртка получилась немного неровной и очень заметной.\n\nНика её обожала.\n\nВ понедельник она впервые пришла в ней в школу.\n\n— Ого, — сказала подруга Ася. — Ты сама?\n\n— С мамой только краску закрепляли.\n\nНа перемене двое мальчиков из параллели прошли мимо.\n\n— Смотрите, космонавт!\n\nНика сначала улыбнулась. Космонавт звучало даже неплохо.\n\nНо на следующей перемене один из них сказал:\n\n— Эй, планетарий, билетики продаёшь?\n\nДругой засмеялся.\n\nНа следующий день:\n\n— Звездочётка идёт!\n\nПотом они начали специально изображать запуск ракеты, когда Ника проходила по коридору.\n\nНика старалась не реагировать.\n\nНо уже в среду утром она достала куртку из шкафа и положила обратно.\n\nНадела серую толстовку.\n\nВ школе никто ничего не сказал.\n\nИ от этого стало одновременно легче и хуже.\n\nНа кружке астрономии руководитель заметил:\n\n— А где твой Сатурн?\n\nНика пожала плечами.\n\n— Надоел.\n\nПосле занятия Ася спросила:\n\n— Они опять?\n\nНика кивнула.\n\n— Может, просто не обращать внимания?\n\n— Я и не обращаю. Вроде.\n\nНо дома она поняла, что всё-таки обращает. Иначе куртка висела бы не в шкафу.\n\nМама увидела её у двери в серой толстовке.\n\n— Куртку не носишь?\n\nНика долго молчала, а потом рассказала.\n\nОна боялась, что мама сразу позвонит чьим-нибудь родителям и станет ещё хуже.\n\n— Я не хочу скандала.\n\n— Хорошо, — сказала мама. — Давай сначала решим, какой помощи ты хочешь.\n\nОни договорились поговорить с классным руководителем вместе, но без большого разбирательства при всём классе.\n\nНа следующий день учительница выслушала Нику.\n\n— Это происходит несколько дней?\n\n— Да.\n\n— Ты просила их остановиться?\n\n— Один раз сказала, что не смешно. Они засмеялись ещё сильнее.\n\n— Тогда это уже не задача, которую ты должна решать одна.\n\nУчительница поговорила с мальчиками отдельно и с дежурным педагогом на этаже. Не о «вкусах в одежде», а о повторяющихся насмешках после просьбы прекратить.\n\nВ четверг один мальчик подошёл к Нике.\n\n— Мы просто шутили.\n\nНика почувствовала знакомое желание сказать: «Да ладно, всё нормально», чтобы разговор быстрее закончился.\n\nНо ответила:\n\n— Мне не было смешно. Я просила остановиться.\n\nОн пожал плечами.\n\n— Ладно.\n\nЭто было не идеальное извинение. Но в тот день запусков ракеты в коридоре не было.\n\nВ пятницу в школе проходил вечер науки.\n\nНика долго смотрела на синюю куртку.\n\nМожно было надеть её.\n\nМожно было не надевать.\n\nМама не спрашивала.\n\nНика всё-таки надела.\n\nНа вечере кружок астрономии устроил игру: в тёмном зале нужно было искать созвездия по маленьким отражающим меткам.\n\nСвет выключили.\n\nЛуч фонарика прошёл по стенам.\n\nИ вдруг Сатурн на спине Ники ярко блеснул — мама случайно купила отражающую краску для кольца.\n\n— Смотрите! — крикнул кто-то. — У Ники Сатурн светится!\n\nДети окружили её.\n\n— Как ты это сделала?\n\n— Можно такую краску на мой рюкзак?\n\nНика улыбалась, но ей было важно другое.\n\nКуртка не стала «правильной» только потому, что понравилась другим. Она нравилась Нике и раньше.\n\nПосле вечера один из тех мальчиков остановился рядом.\n\n— Сатурн реально классный.\n\nНика не знала, что ответить.\n\n— Спасибо.\n\nНа этом всё.\n\nВ понедельник она снова пришла в куртке.\n\nА во вторник выбрала серую толстовку — потому что захотелось.\n\nТеперь это было её решение, а не способ сделать себя менее заметной.\n\nНа рукаве куртки позже появилась ещё одна нашивка — маленькая комета.\n\nНика пришила её немного криво.\n\nТак даже лучше: комета как раз летела куда-то в свою сторону.\n\nЧерез несколько недель в школе появился новый ученик с очень яркими жёлтыми кроссовками. На перемене кто-то бросил вслед:\n\n— Сигнальные маяки!\n\nНика услышала и заметила, как мальчик сразу посмотрел вниз.\n\nОна не стала читать ему лекцию о смелости.\n\nПросто подошла:\n\n— Мне нравится цвет.\n\nОн улыбнулся.\n\nПозже насмешка повторилась. Ника увидела, что мальчик молчит так же, как когда-то молчала она.\n\n— Если хочешь, можем вместе сказать дежурному учителю, — предложила она. — Или ты можешь выбрать другого взрослого.\n\nМальчик согласился.\n\nНика вдруг поняла, зачем ей самой тогда понадобилась помощь взрослого. Не для того, чтобы стать «слабой» или чтобы кто-то решил всё за неё.\n\nА чтобы повторяющаяся ситуация перестала быть её личной обязанностью.\n\nНа рукаве её куртки к этому времени уже были Сатурн, Марс, Земля и новая комета.\n\nИногда она всё ещё замечала чужие взгляды.\n\nНо планеты от этого не снимались с орбит.","question":"К кому из взрослых тебе было бы проще всего обратиться, если чьи-то слова или шутки продолжают тебя задевать?","image":"assets/images/stories/kurtka-s-planetami-dlinnaya.webp","audio":"","published":true},{"id":"7-9-03-korotkaya","topicId":"7-9-03","slug":"kurtka-s-planetami-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Меня дразнят","version":"Короткая","duration":"3–5 минут","title":"Куртка с планетами","hero":"Ника","teaser":"Нику дразнят из-за необычной куртки, которую она украсила сама, и ей приходится решать не только что носить, но и кому рассказать о происходящем.","text":"Ника сама украсила тёмно-синюю куртку планетами.\n\nНа спине был Сатурн, на рукаве — Марс, возле кармана — маленькая Земля.\n\nОна очень любила эту куртку.\n\nНо в школе двое мальчиков начали говорить:\n\n— Планетарий идёт!\n\n— Эй, звездочётка!\n\nСначала Ника старалась не обращать внимания.\n\nПотом однажды оставила куртку дома и надела серую толстовку.\n\nСтало тише, но Нике было неприятно, что теперь одежду выбирают чужие шутки.\n\nОна рассказала маме.\n\n— Я не хочу большого скандала, — сказала Ника.\n\nОни вместе поговорили с классным руководителем. Учительница объяснила: если насмешки продолжаются после просьбы остановиться, Ника не обязана разбираться одна.\n\nС мальчиками поговорили отдельно.\n\nОдин позже сказал:\n\n— Мы просто шутили.\n\nНика ответила:\n\n— Мне не было смешно. Я просила остановиться.\n\nВ пятницу был вечер науки.\n\nНика снова надела куртку.\n\nКогда в зале выключили свет, кольца Сатурна неожиданно засветились от фонарика.\n\n— Классно! — закричали дети.\n\nНика улыбнулась.\n\nНо куртка не стала хорошей только потому, что понравилась другим.\n\nОна нравилась Нике ещё до этого.\n\nВ понедельник Ника снова надела её.\n\nА во вторник выбрала серую толстовку — просто потому, что захотелось.\n\nПозже в школе появился мальчик в ярко-жёлтых кроссовках, и кто-то начал дразнить его.\n\nНика увидела, как он смотрит в пол.\n\n— Мне нравится цвет, — сказала она.\n\nКогда насмешки повторились, Ника предложила:\n\n— Если хочешь, можем вместе сказать взрослому.\n\nТеперь она уже знала: обращаться за помощью — не значит, что человек сам «не справился». Повторяющиеся насмешки не должны становиться его личной обязанностью.\n\nА на рукаве Ники к тому времени появилась новая комета.","question":"К кому из взрослых тебе было бы проще всего обратиться, если чьи-то слова или шутки продолжают тебя задевать?","image":"assets/images/stories/kurtka-s-planetami-korotkaya.webp","audio":"","published":true},{"id":"7-9-04-dlinnaya","topicId":"7-9-04","slug":"tretiy-bilet-na-cherdak-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Друг выбрал другого","version":"Длинная","duration":"10–15 минут","title":"Третий билет на чердак","hero":"Даня","teaser":"Когда лучший друг выбирает другого партнёра для проекта, Даня чувствует себя лишним, но школьное приключение показывает, что дружба не всегда помещается в пару.","text":"У Дани и Лёвы было место, которое они называли Штабом.\n\nЭто был старый чердак в доме Лёвы. Там стояли два складных стула, коробка с комиксами и фонарь, который светил только если постучать по нему сбоку.\n\nДва стула.\n\nДве кружки.\n\nДва лучших друга.\n\nПоэтому, когда учительница сказала:\n\n— Для проекта по окружающему миру объединитесь по двое, — Даня даже не повернулся.\n\nОн уже знал, с кем будет.\n\nНо Лёва подошёл к новенькому мальчику Роме.\n\n— Хочешь вместе сделать вулкан? У тебя же есть моторчик для насоса.\n\nДаня услышал это прямо за спиной.\n\nОн ждал, что Лёва добавит: «Если Даня не против».\n\nЛёва не добавил.\n\n— Дань, ты с кем? — спросила учительница.\n\n— Не знаю.\n\nВ груди было ощущение, будто кто-то без спроса занял его складной стул на чердаке.\n\nВ итоге Даня оказался в паре с Соней. Она хотела сделать модель городского пруда и показать, почему в нём летом цветёт вода.\n\n— Можно сделать прозрачные слои, — сказала Соня.\n\n— Угу.\n\nДане было всё равно.\n\nНа перемене Лёва подбежал:\n\n— Мы с Ромой нашли крутой способ сделать дым без огня!\n\n— Поздравляю.\n\n— Ты чего?\n\n— Ничего.\n\nЛёва постоял и ушёл.\n\nПосле школы Даня не пошёл в Штаб.\n\nНа следующий день тоже.\n\nЛёва написал: «Ты придёшь?»\n\nДаня ответил: «Занят».\n\nОн действительно был занят — Соня принесла прозрачные контейнеры, и пруд начал получаться интересным. Но Даня всё равно представлял, как Лёва с Ромой сидят на чердаке на двух стульях.\n\nНа третий день Соня спросила:\n\n— Ты всё время смотришь на Лёву. Вы поссорились?\n\n— Нет.\n\n— Тогда у тебя очень сердитое «нет».\n\nДаня рассказал.\n\nСоня выслушала.\n\n— У меня так было с Лизой. Она пошла на танцы с другой девочкой. Я думала, что меня заменили.\n\n— И что?\n\n— Ничего. Я злилась. Потом мы поговорили. Она всё ещё моя подруга. Просто не только моя.\n\nФраза Дане не понравилась.\n\n«Не только моя» звучало неприятно.\n\nВ день перед презентацией пруд Сони и Дани дал течь. Вода потекла по столу.\n\n— Салфетки! — крикнула Соня.\n\nДаня схватил рулон.\n\nРома увидел их из соседнего кабинета и принёс герметик.\n\n— Вот, у меня от вулкана осталось.\n\nЛёва прибежал с пластиковым подносом.\n\nВчетвером они спасли модель.\n\n— Спасибо, — сказал Даня Роме.\n\nТот пожал плечами:\n\n— У вас крутая штука. Я думал, цветение воды — это просто зелёная грязь.\n\nПосле презентации Лёва догнал Даню у лестницы.\n\n— Ты правда на меня злишься?\n\nДаня хотел снова сказать «нет».\n\nНо устал.\n\n— Да. Я думал, мы всегда в паре.\n\nЛёва нахмурился.\n\n— Я тоже люблю с тобой делать проекты. Просто Рома показал моторчик, и я сразу придумал вулкан.\n\n— А про меня не подумал.\n\n— Не подумал, — признал Лёва. — Прости.\n\nОни молчали.\n\n— На чердаке Рома был? — спросил Даня.\n\n— Нет.\n\nДаня сам удивился, как важно ему было это узнать.\n\nЛёва посмотрел на него.\n\n— Но я хотел позвать его в субботу. Показать Штаб.\n\nУ Дани снова сжалось внутри.\n\nВот он — третий билет.\n\n— Там только два стула.\n\n— Можно принести третий.\n\nТакой простой ответ немного рассердил Даню.\n\nИ одновременно рассмешил.\n\n— Фонарь и на троих будет глючить.\n\n— Тогда Рома узнает правило: стукнуть слева.\n\nВ субботу Даня пришёл первым.\n\nОн поставил третий стул.\n\nПотом подумал и отодвинул его к коробке с комиксами.\n\nКогда пришли Лёва и Рома, первые десять минут Даня чувствовал себя странно. Лёва иногда говорил с Ромой про вулкан, а Даня не понимал.\n\nПотом Рома нашёл старый комикс и спросил:\n\n— Почему здесь на обложке написано «Не открывать после полуночи»?\n\nДаня и Лёва переглянулись.\n\nЭто была их старая шутка.\n\nДаня рассказал историю.\n\nК вечеру у них появился новый план: построить на чердаке маленькую метеостанцию.\n\nВ понедельник Соня спросила:\n\n— Ну что, тебя заменили?\n\nДаня подумал.\n\n— Нет. Но у нас теперь три стула.\n\n— Ужас, — сказала Соня. — Скоро придётся покупать диван.\n\nДаня засмеялся.\n\nЕму всё ещё хотелось иногда быть с Лёвой вдвоём.\n\nИ позже он так и сказал.\n\nА иногда в Штабе стояло три стула.\n\nОказалось, одно не отменяло другое.\n\nЧерез пару недель Даня сам предложил Лёве сходить в магазин комиксов вдвоём.\n\n— Без Ромы? — спросил Лёва.\n\n— Да. Я хочу сегодня только с тобой.\n\nЛёва кивнул:\n\n— Хорошо.\n\nДане понравилось, что это можно сказать прямо, не устраивая проверку дружбы.\n\nВ другой раз Лёва ушёл с Ромой на тренировку, а Даня уже не почувствовал прежней паники. Немного кольнуло — да. Но он знал, что вечером может написать Лёве, а в субботу они снова встретятся.\n\nСоня однажды пришла на чердак посмотреть метеостанцию.\n\n— Четвёртый стул будете ставить? — спросила она.\n\nДаня оглядел тесный Штаб.\n\n— Нет. Четвёртый уже не влезет.\n\nПотом подумал.\n\n— Хотя есть подушка.\n\nТак в Штабе появилась подушка для гостей.\n\nДва старых стула никуда не делись. Просто перестали быть доказательством того, что дружба существует только на двоих.","question":"Что ты чувствуешь, когда близкий друг проводит время с кем-то ещё?","image":"assets/images/stories/tretiy-bilet-na-cherdak-dlinnaya.webp","audio":"","published":true},{"id":"7-9-04-korotkaya","topicId":"7-9-04","slug":"tretiy-bilet-na-cherdak-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Друг выбрал другого","version":"Короткая","duration":"3–5 минут","title":"Третий билет на чердак","hero":"Даня","teaser":"Когда лучший друг выбирает другого партнёра для проекта, Даня чувствует себя лишним, но школьное приключение показывает, что дружба не всегда помещается в пару.","text":"У Дани и Лёвы был тайный Штаб на чердаке.\n\nТам стояли два стула.\n\nДва фонарика.\n\nДва лучших друга.\n\nПоэтому, когда в школе сказали объединиться для проекта по двое, Даня был уверен, что они будут вместе.\n\nНо Лёва предложил новенькому Роме:\n\n— Давай сделаем вулкан?\n\nДаня почувствовал себя лишним.\n\nОн попал в пару с Соней и несколько дней почти не разговаривал с Лёвой.\n\nНаконец Лёва спросил:\n\n— Ты на меня злишься?\n\n— Да. Я думал, мы всегда в паре.\n\n— Я просто увидел моторчик Ромы и сразу придумал вулкан. Про тебя не подумал. Прости.\n\nПотом Лёва сказал:\n\n— Я хотел позвать Рому в Штаб.\n\nУ Дани снова всё сжалось.\n\n— Там только два стула.\n\n— Принесём третий.\n\nВ субботу Даня сам поставил третий складной стул.\n\nСначала было непривычно. Потом Рома нашёл старый комикс, Даня рассказал их с Лёвой смешную историю, и вскоре трое уже придумывали метеостанцию.\n\nДане всё ещё хотелось иногда быть с Лёвой вдвоём.\n\nОн так и сказал.\n\nА иногда на чердаке стояло три стула.\n\nОказалось, одно не отменяло другое.\n\nПозже Даня сам сказал Лёве:\n\n— Сегодня хочу погулять только вдвоём.\n\n— Хорошо, — ответил Лёва.\n\nОказалось, можно просить время вдвоём, не требуя, чтобы друг больше ни с кем не дружил.\n\nА когда в Штаб пришла Соня, четвёртый стул уже не помещался.\n\n— Есть подушка, — решил Даня.\n\nДва старых стула остались на месте.\n\nПросто теперь они больше не были правилом, сколько людей может быть рядом.","question":"Что ты чувствуешь, когда близкий друг проводит время с кем-то ещё?","image":"assets/images/stories/tretiy-bilet-na-cherdak-korotkaya.webp","audio":"","published":true},{"id":"7-9-05-dlinnaya","topicId":"7-9-05","slug":"doska-kotoroy-ne-hvatilo-kolonok-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Сравниваю себя с другими","version":"Длинная","duration":"10–15 минут","title":"Доска, которой не хватило колонок","hero":"Алиса","teaser":"На лагерной доске рекордов Алиса всё время оказывается не первой, пока одно ночное приключение не показывает, сколько важных умений вообще не попадает в таблицы.","text":"В летнем лагере «Сосны» возле столовой висела Доска рекордов.\n\nСамый быстрый бег — Кирилл.\n\nБольше всех подтягиваний — Маша.\n\nЛучший результат по шахматам — Тимур.\n\nСамая высокая башня из палочек — Лиза.\n\nАлиса каждый день останавливалась у доски.\n\nОна бегала нормально, но не быстрее Кирилла.\n\nВ шахматы играла, но Тимур обыгрывал её за десять минут.\n\nБашня Алисы однажды заняла второе место.\n\nВторое.\n\nСнова не первое.\n\nОна стала замечать чужие успехи повсюду.\n\nМаша красиво ныряет.\n\nЛиза умеет рисовать лица.\n\nТимур быстро считает в уме.\n\nКирилл шутит так, что смеётся весь отряд.\n\n«А я что?» — думала Алиса.\n\nНа кружке туризма вожатый дал каждому компас.\n\n— Сегодня вечером будет маршрут по территории. Команда получает точки и собирает код.\n\nАлиса любила карты. Она легко запоминала дорожки и странные ориентиры: сосну с двумя стволами, скамейку без одной планки, камень, похожий на черепаху.\n\nНо на доске рекордов не было колонки «помнит странные камни».\n\nВечером команды вышли на маршрут.\n\nСначала всё шло быстро. Кирилл добежал до первой точки первым. Тимур разгадал шифр. Лиза заметила спрятанный знак на рисунке.\n\nПотом начало темнеть.\n\nНа четвёртой точке у одной девочки, Оли, развязался шнурок. Пока все ждали, соседняя команда ушла вперёд.\n\n— Мы теперь проиграем, — простонал Кирилл.\n\nАлиса посмотрела на карту.\n\n— Можно срезать по тропе за беседкой.\n\n— Там разве есть тропа?\n\n— Есть. Она выходит к камню-черепахе.\n\nОни пошли.\n\nТропа действительно была.\n\nНа пятой точке нужно было построить маленькую переноску для «хрупкого груза» — сырого яйца.\n\nМаша умела вязать узлы, но не могла вспомнить один из них.\n\nАлиса вспомнила, как дедушка показывал ей простой узел для пакетов.\n\n— Можно так попробовать.\n\nНе спортивный рекорд.\n\nПросто сработало.\n\nДальше Оля стала нервничать из-за темноты.\n\n— Я не хочу идти последней.\n\nВсе торопились. Алиса поменялась с ней местами и пошла рядом.\n\n— Смотри, вон фонарь у корпуса. Мы всё время недалеко.\n\nОля кивнула.\n\nНа последней точке команды получили код, но одна цифра была размазана дождём.\n\n— Всё, — сказал Тимур. — Не прочитать.\n\nАлиса посмотрела на предыдущие подсказки.\n\n— Здесь цифры идут по числу букв в названиях точек. Значит, последняя — семь.\n\nТимур проверил.\n\n— Точно.\n\nОни вернулись вторыми.\n\nКирилл сначала расстроился.\n\n— Почти.\n\nВожатый собрал всех.\n\n— Сегодня рекорд скорости поставила соседняя команда. А ещё я хочу отметить, как ваша команда не потеряла участника, нашла короткую тропу и восстановила код.\n\nАлиса почувствовала, что сейчас он скажет её имя, и почему-то смутилась.\n\nНо вожатый не стал добавлять новую строку на Доску рекордов.\n\nНа следующий день Алиса сама взяла мел и нарисовала сбоку маленькую табличку.\n\n«Что ещё умеют люди».\n\nПод ней написала:\n\nОля — замечает, когда кто-то отстал.\n\nТимур — объясняет сложные правила.\n\nКирилл — умеет рассмешить, когда все устали.\n\nЛиза — видит детали.\n\nМаша — не бросает после первой неудачи.\n\nПотом остановилась.\n\nЧто написать про себя?\n\nДолго думала.\n\nНаконец вывела:\n\nАлиса — помнит дорогу и собирает кусочки в целую картину.\n\nК обеду кто-то добавил новые строки.\n\n«Саша умеет мирить».\n\n«Дина знает песни».\n\n«Рома чинит молнии на рюкзаках».\n\nТабличка разрослась так, что не поместилась сбоку. Пришлось взять второй лист.\n\nДоска рекордов никуда не исчезла.\n\nАлиса всё ещё хотела однажды увидеть своё имя в колонке «самая высокая башня».\n\nНо теперь, проходя мимо, она смотрела не только вверх таблицы.\n\nРядом висел второй лист, которому постоянно не хватало места.\n\nЧерез несколько дней на Доске рекордов появилась новая строка: «Самая быстрая сборка палатки».\n\nАлиса вместе с Машей и Тимуром решила попробовать.\n\nОни не выиграли. Зато собрали палатку без споров и не забыли растяжки.\n\nАлиса заметила, что теперь может смотреть на имя победителя без автоматического вопроса: «Почему не я?»\n\nИногда этот вопрос всё равно появлялся.\n\nТогда она читала второй лист.\n\nОднажды кто-то дописал:\n\n«Алиса — замечает, когда человек уже устал спорить и предлагает другой способ».\n\nОна удивилась.\n\n— Это кто написал?\n\nНикто не признался.\n\nЭта строчка понравилась ей особенно, потому что сама Алиса никогда не подумала бы назвать это умением.\n\nВ последний день лагеря второй лист сняли со стены. Он был исписан с двух сторон.\n\nДоска рекордов выглядела аккуратно и законченно.\n\nА лист «Что ещё умеют люди» был весь в стрелках, приписках и новых строках.\n\nАлисе почему-то именно он казался точнее.","question":"Какое твоё умение трудно измерить баллами, секундами или местом в соревновании?","image":"assets/images/stories/doska-kotoroy-ne-hvatilo-kolonok-dlinnaya.webp","audio":"","published":true},{"id":"7-9-05-korotkaya","topicId":"7-9-05","slug":"doska-kotoroy-ne-hvatilo-kolonok-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Сравниваю себя с другими","version":"Короткая","duration":"3–5 минут","title":"Доска, которой не хватило колонок","hero":"Алиса","teaser":"На лагерной доске рекордов Алиса всё время оказывается не первой, пока одно ночное приключение не показывает, сколько важных умений вообще не попадает в таблицы.","text":"В лагере возле столовой висела Доска рекордов.\n\nСамый быстрый — Кирилл.\n\nЛучший в шахматах — Тимур.\n\nСамая высокая башня — у Лизы.\n\nАлиса каждый день смотрела и думала:\n\n«А я в чём лучшая?»\n\nОднажды отряд пошёл по вечернему маршруту с картой.\n\nКирилл быстро бегал.\n\nТимур разгадывал шифры.\n\nЛиза замечала спрятанные знаки.\n\nА потом команда отстала.\n\n— Можно срезать по тропе за беседкой, — сказала Алиса. — Она выходит к камню-черепахе.\n\n— Ты уверена?\n\n— Я помню.\n\nТропа была на месте.\n\nПозже Алиса вспомнила нужный узел, помогла девочке, которой стало неуютно в темноте, и догадалась о размазанной цифре в коде.\n\nКоманда пришла второй.\n\nНа следующий день Алиса взяла мел и рядом с Доской рекордов написала:\n\n«Что ещё умеют люди».\n\nТам появились строки:\n\n«умеет рассмешить»,\n\n«замечает детали»,\n\n«не бросает после неудачи».\n\nПро себя Алиса написала:\n\n«Помнит дорогу и собирает кусочки в целую картину».\n\nДоска рекордов осталась.\n\nА рядом появился второй лист.\n\nИ ему очень быстро перестало хватать места.\n\nПозже Алиса с друзьями участвовала в сборке палатки.\n\nОни не стали первыми.\n\nНо сделали всё спокойно и правильно.\n\nНа листе «Что ещё умеют люди» кто-то написал про Алису:\n\n«Замечает, когда все уже устали спорить, и предлагает другой способ».\n\nОна удивилась: сама бы никогда не назвала это умением.\n\nК концу смены Доска рекордов оставалась аккуратной.\n\nА второй лист был исписан с двух сторон.\n\nАлисе именно он казался похожим на настоящих людей.","question":"Какое твоё умение трудно измерить баллами, секундами или местом в соревновании?","image":"assets/images/stories/doska-kotoroy-ne-hvatilo-kolonok-korotkaya.webp","audio":"","published":true},{"id":"7-9-06-dlinnaya","topicId":"7-9-06","slug":"orkestr-bez-pervogo-mesta-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Боюсь быть хуже","version":"Длинная","duration":"10–15 минут","title":"Оркестр без первого места","hero":"Ринат","teaser":"Ринат боится оказаться самым слабым музыкантом на школьном концерте, пока неожиданная поломка не заставляет оркестр слушать друг друга по-настоящему.","text":"Ринат играл на кахоне — деревянном ящике, который мог звучать как барабан.\n\nБум.\n\nТа-та.\n\nШух.\n\nЕму нравилось, что из одного инструмента можно достать десятки разных звуков.\n\nНо к школьному концерту в ансамбль пришёл новый мальчик, Дамир. Он играл на ударных так быстро, что палочки будто исчезали.\n\nТа-ра-та-та-та!\n\nПосле первой репетиции вокруг него собрались ребята.\n\n— Как ты это делаешь?\n\n— А можешь ещё быстрее?\n\nРинат сидел на своём кахоне и думал:\n\n«Рядом с ним я вообще ничего не умею».\n\nДома он стал тренироваться быстрее.\n\nОчень быстро.\n\nТак быстро, что перестал попадать в ритм.\n\nМама из кухни спросила:\n\n— Это новая песня?\n\n— Нет.\n\n— Тогда почему она убегает?\n\n— Потому что я медленный.\n\nНа следующей репетиции Ринат всё время слушал Дамира.\n\nЕсли Дамир делал сложный переход, Ринат пытался придумать ещё сложнее.\n\nЕсли Дамир ускорялся, Ринат тоже ускорялся.\n\nВ середине песни скрипачка Вика остановилась.\n\n— Мы развалились.\n\nРуководитель ансамбля поднял руку.\n\n— Ещё раз. И на этот раз слушаем не себя, а песню.\n\nРинат кивнул, но внутри всё равно считал:\n\n«Дамир быстрее. Дамир громче. Дамир лучше».\n\nВ день концерта актовый зал был полон.\n\nАнсамбль вышел на сцену.\n\nПервая песня прошла хорошо.\n\nВо второй произошло то, чего никто не ждал.\n\nУ Дамира сломалась педаль большого барабана.\n\nЩёлк.\n\nНога нажала — звука нет.\n\nДамир посмотрел вниз.\n\nРуководитель уже поднял руки, будто хотел остановить номер.\n\nНо песня продолжалась.\n\nСкрипки играли.\n\nГитара держала аккорды.\n\nИ в этот момент Ринат понял: без большого барабана пропала нижняя доля — то самое тяжёлое «бум», на которое все опирались.\n\nОн ударил по центру кахона.\n\nБум.\n\nГитарист сразу повернул голову.\n\nРинат повторил.\n\nБум.\n\nБум.\n\nДамир понял и переключился на малый барабан руками.\n\nТеперь они играли вместе: Ринат держал тяжёлый пульс, Дамир добавлял лёгкие дроби.\n\nНикто не пытался быть быстрее.\n\nНужно было просто не потерять песню.\n\nК концу номера зал хлопал в такт.\n\nПосле концерта Дамир первым подошёл к Ринату.\n\n— Ты нас вытащил.\n\n— Я просто делал «бум».\n\n— Именно его и не хватало.\n\nРинат засмеялся.\n\nОн всё ещё считал Дамира очень сильным музыкантом. И всё ещё хотел научиться некоторым его переходам.\n\nНа следующей репетиции он попросил:\n\n— Покажешь вот этот кусок?\n\n— Конечно. А ты покажешь, как ты делаешь такой сухой звук по краю кахона?\n\nРинат показал.\n\nЧерез несколько недель они играли новый номер.\n\nВ нём у Дамира было быстрое соло.\n\nУ Рината — всего четыре удара перед припевом.\n\nБум.\n\nПауза.\n\nБум-бум.\n\nПауза.\n\nРаньше Ринату показалось бы, что четыре удара — слишком мало, чтобы быть важными.\n\nНо теперь он услышал, как весь ансамбль ждёт именно их.\n\nПосле последнего «бум» музыка раскрылась целиком.\n\nВ оркестре действительно не было таблички, кто первый, второй или хуже всех.\n\nЗато было очень хорошо слышно, когда кто-то переставал слушать остальных.\n\nЧерез неделю ансамбль получил новое задание: придумать короткую музыкальную заставку для школьного радио.\n\nКаждому предложили свой вариант.\n\nДамир сыграл сложную дробь.\n\nВика — красивую мелодию.\n\nРинат долго ничего не предлагал. Ему казалось, что его четыре удара снова будут слишком простыми.\n\nПотом он постучал:\n\nбум — та — пауза — бум.\n\nВсе замолчали.\n\n— Повтори, — попросила Вика.\n\nРинат повторил.\n\nДамир сверху добавил лёгкий шорох щётками, гитара взяла два аккорда.\n\nПолучилось коротко, но запоминалось.\n\nИменно эту заставку выбрали для эфира.\n\nКогда Ринат услышал её из школьного динамика, он улыбнулся.\n\nИногда он всё ещё сравнивал себя с Дамиром и замечал, чего пока не умеет.\n\nНо теперь рядом с этим появлялся другой вопрос:\n\n«А что здесь нужно музыке?»\n\nИногда ответом была быстрая дробь.\n\nА иногда — один точный удар после паузы.","question":"В каком деле тебе особенно важно не казаться хуже других и почему?","image":"assets/images/stories/orkestr-bez-pervogo-mesta-dlinnaya.webp","audio":"","published":true},{"id":"7-9-06-korotkaya","topicId":"7-9-06","slug":"orkestr-bez-pervogo-mesta-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Боюсь быть хуже","version":"Короткая","duration":"3–5 минут","title":"Оркестр без первого места","hero":"Ринат","teaser":"Ринат боится оказаться самым слабым музыкантом на школьном концерте, пока неожиданная поломка не заставляет оркестр слушать друг друга по-настоящему.","text":"Ринат играл на кахоне — деревянном ящике-барабане.\n\nВ школьный ансамбль пришёл Дамир. Он играл на ударных очень быстро.\n\nТа-ра-та-та-та!\n\nВсе восхищались.\n\nРинат подумал:\n\n«Рядом с ним я хуже всех».\n\nОн стал тренироваться быстрее и на репетициях всё время пытался догнать Дамира.\n\nВ итоге музыка начинала разваливаться.\n\nНа концерте у Дамира неожиданно сломалась педаль большого барабана.\n\nЩёлк.\n\nПропал тяжёлый удар, на который опирался весь ансамбль.\n\nРинат ударил по центру кахона:\n\nБум.\n\nПотом ещё раз.\n\nБум.\n\nГитара подхватила ритм.\n\nДамир переключился на малый барабан.\n\nТеперь они играли вместе: Ринат держал пульс, Дамир добавлял быстрые дроби.\n\nПосле концерта Дамир сказал:\n\n— Ты нас вытащил.\n\n— Я просто делал «бум».\n\n— Именно его и не хватало.\n\nНа следующей репетиции Ринат попросил Дамира показать сложный переход.\n\nА Дамир попросил научить его особому звуку кахона.\n\nРинат всё ещё восхищался его скоростью.\n\nНо теперь знал: в музыке иногда четыре точных удара важнее сорока быстрых.\n\nПозже ансамбль придумывал короткую заставку для школьного радио.\n\nРинату казалось, что его простой ритм слишком обычный.\n\nОн всё же сыграл:\n\nбум — та — пауза — бум.\n\nВика добавила мелодию, Дамир — лёгкую дробь.\n\nИменно эту заставку выбрали.\n\nУслышав её из школьного динамика, Ринат улыбнулся.\n\nТеперь он иногда спрашивал не «кто здесь лучше?», а «что сейчас нужно музыке?»","question":"В каком деле тебе особенно важно не казаться хуже других и почему?","image":"assets/images/stories/orkestr-bez-pervogo-mesta-korotkaya.webp","audio":"","published":true},{"id":"7-9-07-dlinnaya","topicId":"7-9-07","slug":"karta-malenkih-umeniy-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Мне кажется, что я ничего не умею","version":"Длинная","duration":"10–15 минут","title":"Карта маленьких умений","hero":"Глеб","teaser":"После нескольких неудач Глеб уверен, что ни в чём не хорош, пока походный день не собирает его незаметные навыки в одну важную цепочку.","text":"За первые три дня в школьном лагере Глеб успел проиграть в футбол, занять последнее место в эстафете и сделать глиняную чашку, которая была больше похожа на сплющенный ботинок.\n\n— У меня талант, — сказал он другу. — Я умею быть плохим сразу во всём.\n\nДруг засмеялся, но Глеб говорил почти серьёзно.\n\nНа четвёртый день отряд отправился в поход к старой водонапорной башне. Маршрут был несложный: лесная тропа, ручей, холм и обратно.\n\nВожатый раздал небольшие рюкзаки.\n\n— Сегодня никто не соревнуется. Задача — прийти всей группой и вернуться всей группой.\n\nГлеб пожал плечами.\n\n«Вот и хорошо. Хотя бы проигрывать некому».\n\nНа первой развилке ребята начали спорить.\n\n— Налево!\n\n— Нет, направо!\n\nУказатель оказался выцветшим.\n\nГлеб посмотрел вокруг.\n\n— Мы утром проходили мимо сосны с белой полосой. Она была справа от дороги. Если возвращаемся к ручью с другой стороны, нам сюда.\n\n— Ты запомнил? — удивилась Вера.\n\n— Просто заметил.\n\nОни пошли и через пять минут вышли к нужному мостику.\n\nУ ручья у младшего мальчика Паши заело молнию на рюкзаке.\n\n— Она сломалась!\n\nГлеб присел.\n\n— Не тяни. Тут ткань попала в бегунок.\n\nОн осторожно вытащил край ткани.\n\nМолния снова поехала.\n\n— Откуда ты умеешь?\n\n— У меня на куртке всё время так.\n\nДальше Вера подвернула шнурок вокруг ветки и упала. Ничего серьёзного, но колено заболело.\n\nПока вожатый доставал аптечку, Глеб сел рядом.\n\n— Хочешь, расскажу, как мой кот однажды испугался огурца и врезался в коробку?\n\nВера фыркнула.\n\n— Это правда?\n\n— Почти.\n\nПока он рассказывал, она перестала плакать.\n\nНа привале нужно было развести маленький учебный костёр в металлической чаше. Спички зажигал взрослый, а ребята собирали сухие веточки.\n\nВсе хватали самые большие.\n\nГлеб потрогал их.\n\n— Эти сырые. Под корнями есть сухая мелочь.\n\n— Откуда знаешь?\n\n— Дед показывал.\n\nКостёр разгорелся именно с тонких сухих веточек.\n\nК башне они пришли позже соседнего отряда.\n\nНикакого места за это не дали.\n\nВожатый достал карту и предложил каждому поставить на ней маленькую отметку там, где он был полезен группе.\n\nКто-то отметил «быстро донёс воду».\n\nКто-то — «нашла перевязочный пакет».\n\nГлеб сначала не знал, что писать.\n\nПотом Вера сказала:\n\n— Ты дорогу вспомнил.\n\nПаша добавил:\n\n— И молнию починил.\n\n— И костёр, — сказал кто-то.\n\nГлеб нарисовал три маленькие точки.\n\nПолучилась почти линия.\n\nНа обратном пути он начал замечать больше.\n\nЛена умела замечать мусор и собирать его в пакет.\n\nПаша смешно изображал птиц и угадывал их по голосу.\n\nВера читала карту лучше всех.\n\nНикто из них не был «лучшим вообще».\n\nТакой категории просто не существовало.\n\nВ лагере Глеб всё равно не стал звездой футбола.\n\nНа следующей игре он снова промахнулся по воротам.\n\n— Ну вот, — автоматически сказал он. — Я ничего…\n\nИ остановился.\n\n— В футболе сегодня не очень.\n\nЭто звучало точнее.\n\nПосле игры Паша принёс рюкзак.\n\n— Снова молния.\n\nГлеб рассмеялся.\n\n— Кажется, у меня открылась мастерская.\n\nВ конце смены вожатый вернул всем походную карту. На карте Глеба было уже не три точки, а целая россыпь маленьких пометок.\n\nНи одна сама по себе не выглядела как большой талант.\n\nНо вместе они показывали маршрут, по которому группа действительно прошла дальше.\n\nВ конце смены в лагере устроили «день наоборот»: каждый должен был научить других чему-то маленькому, что умеет сам.\n\nКирилл показывал футбольный финт.\n\nЛиза — как смешивать два цвета без грязного оттенка.\n\nГлеб сначала хотел отказаться.\n\n— А я чему научу?\n\nПаша поднял свой рюкзак.\n\n— Молнии.\n\nВсе засмеялись.\n\nГлеб показал, как не тянуть бегунок силой, если в него попала ткань.\n\nПотом рассказал, как замечать ориентиры на дороге: не просто «дерево», а «сосна с белой полосой», не просто «камень», а «камень-черепаха».\n\nУ его маленького занятия неожиданно собралась половина отряда.\n\nНа следующий день девочка подбежала:\n\n— Глеб! Я сама вытащила ткань из молнии!\n\nЭто не было медалью.\n\nНо почему-то запомнилось сильнее, чем второе место в любой эстафете.\n\nУезжая из лагеря, Глеб забрал карту с точками домой.\n\nОн повесил её над столом.\n\nНе как доказательство, что теперь «умеет всё».\n\nА как напоминание, что фраза «ничего не умею» слишком большая для настоящего человека.","question":"Какие маленькие вещи у тебя хорошо получаются, хотя за них обычно не дают медалей?","image":"assets/images/stories/karta-malenkih-umeniy-dlinnaya.webp","audio":"","published":true},{"id":"7-9-07-korotkaya","topicId":"7-9-07","slug":"karta-malenkih-umeniy-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Мне кажется, что я ничего не умею","version":"Короткая","duration":"3–5 минут","title":"Карта маленьких умений","hero":"Глеб","teaser":"После нескольких неудач Глеб уверен, что ни в чём не хорош, пока походный день не собирает его незаметные навыки в одну важную цепочку.","text":"За три дня в лагере Глеб проиграл в футбол, пришёл последним в эстафете и слепил очень кривую чашку.\n\n— Я ничего не умею, — решил он.\n\nНа следующий день отряд пошёл в поход.\n\nНа развилке все забыли дорогу.\n\n— Мы проходили мимо сосны с белой полосой, — сказал Глеб. — Значит, нам сюда.\n\nЧерез несколько минут они вышли к нужному мосту.\n\nПотом у младшего мальчика заело молнию на рюкзаке.\n\n— Тут ткань попала, — заметил Глеб и аккуратно освободил бегунок.\n\nНа привале ребята собирали ветки для учебного костра.\n\n— Эти сырые. Лучше взять тонкие под корнями.\n\nКостёр быстро разгорелся.\n\nУ старой башни вожатый предложил каждому отметить на карте места, где он был полезен группе.\n\n— Ты дорогу вспомнил, — сказала Вера.\n\n— И молнию починил, — добавил Паша.\n\n— И сухие ветки нашёл.\n\nНа карте Глеба появились три точки.\n\nПосле похода он снова промахнулся в футболе.\n\n— Я ничего… — начал он.\n\nПотом исправился:\n\n— В футболе сегодня не очень.\n\nА через минуту Паша принёс рюкзак:\n\n— Поможешь с молнией?\n\nГлеб улыбнулся.\n\nКажется, одно из его маленьких умений уже точно кому-то пригодилось.\n\nВ конце смены каждый должен был научить других чему-то маленькому.\n\n— А я чему? — спросил Глеб.\n\n— Молниям! — подсказал Паша.\n\nГлеб показал, как освобождать ткань из заевшего бегунка и как запоминать дорогу по необычным ориентирам.\n\nЕго занятие оказалось неожиданно популярным.\n\nНа следующий день девочка радостно сказала:\n\n— Я сама починила молнию!\n\nГлеб забрал походную карту домой.\n\nОна напоминала: «ничего не умею» — слишком большая фраза. Почти всегда можно найти что-то точнее.","question":"Какие маленькие вещи у тебя хорошо получаются, хотя за них обычно не дают медалей?","image":"assets/images/stories/karta-malenkih-umeniy-korotkaya.webp","audio":"","published":true},{"id":"7-9-08-dlinnaya","topicId":"7-9-08","slug":"signal-na-kryshe-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Сложно просить помощи","version":"Длинная","duration":"10–15 минут","title":"Сигнал на крыше","hero":"Соня","teaser":"Соня хочет построить метеостанцию полностью сама, но застрявший флюгер на крыше клуба заставляет её придумать способ просить помощь без ощущения поражения.","text":"В школьном клубе изобретателей объявили неделю «Сделай сам».\n\nСоня решила построить маленькую метеостанцию: флюгер, дождемер и шкалу ветра.\n\n— Хочешь, будем делать вместе? — спросил Никита.\n\n— Нет. Это же «Сделай сам».\n\nСоня особенно хотела доказать себе, что справится без подсказок.\n\nОна нарисовала чертёж.\n\nСделала стрелку флюгера из плотного картона.\n\nНашла трубочку, шайбу и палочку.\n\nПервый вариант не вращался.\n\nСоня никому не сказала.\n\nВторой вращался только если на него дуть очень сильно.\n\nОна снова никому не сказала.\n\nТретий вращался прекрасно, но стрелка всё время смотрела хвостом вперёд.\n\nНикита проходил мимо:\n\n— Кажется, у тебя…\n\n— Всё нормально.\n\nК пятнице нужно было установить станции во дворе.\n\nСоня поднялась на невысокую плоскую крышу клубного сарая вместе с руководителем. Взрослый держал лестницу и следил за безопасностью, а Соня должна была закрепить флюгер на стойке.\n\nГайка никак не попадала на резьбу.\n\nСоня попробовала раз.\n\nДругой.\n\nЕщё.\n\nВнизу ребята уже закончили свои приборы.\n\n— Нужен другой ключ? — спросил руководитель.\n\n— Нет, я сама.\n\nПальцы устали.\n\nВетер шевелил картонную стрелку.\n\nСоня всё сильнее злилась.\n\nНаконец гайка выскользнула и укатилась под вентиляционную коробку.\n\n— Отлично, — пробормотала она.\n\nДостать рукой было нельзя.\n\nРуководитель спросил:\n\n— Что ты хочешь сделать?\n\nСоня знала, что можно попросить длинный магнитный захват из мастерской. Но это означало сказать вслух: «Мне нужна помощь».\n\nЕй почему-то казалось, что тогда вся её метеостанция перестанет считаться «самостоятельной».\n\n— Я придумаю.\n\nОна взяла тонкую палочку.\n\nНе достала.\n\nСделала крючок из проволоки.\n\nГайка отодвинулась ещё дальше.\n\nСоня села на корточки.\n\nВнизу на столе лежали цветные карточки, которые клуб использовал для экспериментов.\n\nЗелёная — «всё идёт».\n\nЖёлтая — «нужен совет».\n\nКрасная — «нужны ещё руки».\n\nСоня сама когда-то предложила эти карточки для командной работы.\n\nТеперь ей стало смешно.\n\nОна могла придумать систему для других — и не пользоваться ею сама.\n\nСоня попросила руководителя передать жёлтую карточку Никите.\n\nЧерез минуту он поднял голову.\n\n— Совет?\n\n— У меня гайка укатилась туда. Крючком только хуже.\n\nНикита не полез на крышу. Он подумал снизу.\n\n— Магнитный захват?\n\n— Точно.\n\n— Принести?\n\nСоня кивнула.\n\nЧерез две минуты инструмент был у неё.\n\nГайка прилипла к магниту:\n\nщелк.\n\n— Есть!\n\nНо дальше выяснилось, что ключ действительно слишком большой для этой гайки.\n\nСоня посмотрела вниз.\n\n— Никит!\n\n— Что?\n\n— Теперь красная карточка. Нужен маленький ключ!\n\nВсе засмеялись.\n\nМаленький ключ нашёлся у Леры.\n\nФлюгер закрепили.\n\nКогда Соня спустилась, ей не казалось, что станцию сделал кто-то вместо неё.\n\nЧертёж был её.\n\nТри неудачных варианта — тоже её.\n\nРешения принимала она.\n\nА магнитный захват и ключ просто помогли сделать то, для чего нужны были другие вещи и люди.\n\nНа выставке рядом с метеостанцией Соня прикрепила три маленькие карточки.\n\nЗелёную.\n\nЖёлтую.\n\nКрасную.\n\nПодписала:\n\n«Самостоятельность — это не всегда делать всё одной. Иногда это замечать, какая помощь нужна».\n\nПотом перечитала и зачеркнула последнюю фразу — показалась слишком взрослой для таблички.\n\nВместо неё написала проще:\n\n«Если застрял — выбери сигнал».\n\nЧерез неделю Никита мучился с программой для робота.\n\nСоня прошла мимо.\n\n— Всё нормально? — спросила она.\n\n— Конечно.\n\nЧерез десять минут на её стол тихо легла жёлтая карточка.\n\nСоня улыбнулась.\n\n— Показывай.\n\nЧерез несколько дней Соня заметила ещё одну трудность: иногда она просила помощь слишком поздно, когда уже злилась на всех вокруг.\n\nОна придумала для себя новое правило.\n\nЕсли три попытки подряд приводят к одному и тому же результату, нужно остановиться и решить: попробовать по-другому, поискать информацию или попросить человека.\n\nЭто правило пригодилось почти сразу.\n\nНа уроке технологии Соня не могла сделать ровный шов. После третьей кривой строчки она уже хотела спрятать ткань.\n\nПотом вспомнила правило.\n\n— Можно покажете, где я держу иглу неправильно? — спросила она учительницу.\n\nОказалось, Соня слишком сильно натягивала ткань.\n\nЧерез несколько стежков линия стала ровнее.\n\nПомощь не сделала работу чужой.\n\nОна просто сэкономила Соне ещё десять кривых строчек и плохое настроение.\n\nЖёлтая карточка теперь лежала у неё в пенале рядом с линейкой.\n\nНе как знак «я не справилась».\n\nКак один из инструментов.","question":"В какой момент тебе обычно становится легче попросить о помощи — сразу или когда уже совсем не получается?","image":"assets/images/stories/signal-na-kryshe-dlinnaya.webp","audio":"","published":true},{"id":"7-9-08-korotkaya","topicId":"7-9-08","slug":"signal-na-kryshe-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Сложно просить помощи","version":"Короткая","duration":"3–5 минут","title":"Сигнал на крыше","hero":"Соня","teaser":"Соня хочет построить метеостанцию полностью сама, но застрявший флюгер на крыше клуба заставляет её придумать способ просить помощь без ощущения поражения.","text":"Соня решила построить метеостанцию полностью сама.\n\n— Хочешь помочь? — спросил Никита.\n\n— Нет. Я справлюсь.\n\nФлюгер пришлось переделать три раза.\n\nВ пятницу Соня стала крепить его на невысокой крыше клубного сарая. Взрослый был рядом и следил за безопасностью.\n\nГайка никак не закручивалась.\n\nПотом выскользнула и укатилась туда, куда рукой не достать.\n\nСоня попробовала палочку.\n\nНе вышло.\n\nСделала крючок.\n\nСтало только хуже.\n\nВ клубе были карточки:\n\nзелёная — «всё идёт»,\n\nжёлтая — «нужен совет»,\n\nкрасная — «нужны ещё руки или инструмент».\n\nСоня сама когда-то придумала эту систему.\n\nОна вздохнула и попросила передать Никите жёлтую карточку.\n\n— У меня гайка укатилась.\n\n— Возьми магнитный захват, — предложил он.\n\nЩёлк!\n\nГайка сразу нашлась.\n\nПотом понадобился маленький ключ.\n\n— Теперь красная карточка! — крикнула Соня вниз.\n\nФлюгер установили.\n\nОн вращался на ветру именно так, как Соня задумала.\n\nСтанция не перестала быть её работой из-за того, что кто-то принёс инструмент.\n\nНа выставке Соня повесила рядом три карточки и короткую надпись:\n\n«Если застрял — выбери сигнал».\n\nСоня придумала ещё одно правило: если три попытки подряд дают один и тот же плохой результат, нужно остановиться и выбрать — другой способ, информация или помощь.\n\nНа технологии после третьего кривого шва она спросила учительницу:\n\n— Покажете, что я делаю не так?\n\nОказалось, Соня слишком натягивала ткань.\n\nШов стал ровнее.\n\nЖёлтая карточка теперь лежала у неё в пенале рядом с линейкой.\n\nПросто ещё один инструмент.","question":"В какой момент тебе обычно становится легче попросить о помощи — сразу или когда уже совсем не получается?","image":"assets/images/stories/signal-na-kryshe-korotkaya.webp","audio":"","published":true},{"id":"7-9-09-dlinnaya","topicId":"7-9-09","slug":"ischeznuvshaya-papka-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Стыдно признаться в ошибке","version":"Длинная","duration":"10–15 минут","title":"Исчезнувшая папка","hero":"Марк","teaser":"Марк случайно удаляет общую презентацию и пытается скрыть случившееся, но исправить ошибку удаётся только после того, как команда узнаёт правду.","text":"До школьной конференции оставалось два дня.\n\nКоманда Марка делала презентацию о старых зданиях города. Лиза собирала фотографии, Юра рисовал карту, Марк отвечал за оформление.\n\nВ общей папке лежало всё.\n\nДвадцать три фотографии.\n\nШесть слайдов.\n\nТаблица с датами.\n\nИ файл «ФИНАЛ_ТОЧНО_ФИНАЛ».\n\nВечером Марк решил навести порядок.\n\nОн удалил старые картинки, пустые черновики и папку с названием «временное».\n\nКомпьютер спросил:\n\n«Удалить?»\n\nМарк нажал «Да».\n\nЧерез секунду папка исчезла.\n\nИ вместе с ней — почти все фотографии Лизы.\n\nМарк замер.\n\nОн открыл корзину.\n\nПусто.\n\nОбновил страницу.\n\nНичего.\n\nВнутри стало холодно.\n\n«Если сказать, все решат, что я всё испортил».\n\nОн написал в общий чат:\n\n«У кого-нибудь открываются фотки? У меня что-то пропали».\n\nЛиза ответила:\n\n«Что значит пропали?»\n\nМарк набрал: «Я случайно удалил».\n\nПотом стёр.\n\nНаписал:\n\n«Наверное, сайт глючит».\n\nНа следующий день команда собралась в библиотеке.\n\nЛиза была в ужасе.\n\n— Я эти фотографии два вечера собирала!\n\nЮра сказал:\n\n— Может, они сами исчезли?\n\nМарк молчал.\n\nУчитель подошёл.\n\n— Что случилось?\n\n— Файлы пропали.\n\n— Кто последним работал с папкой?\n\nМарк почувствовал, как уши становятся горячими.\n\n— Я… но я только оформление делал.\n\nЭто было почти правдой и совсем не правдой.\n\nВсе начали искать резервные копии.\n\nЛиза снова ездила к бабушке за фотографией старого дома.\n\nЮра скачивал изображения заново.\n\nМарк помогал, но от этого становилось только хуже.\n\nПотому что команда исправляла проблему, не зная её настоящей причины.\n\nПосле часа поисков учитель сказал:\n\n— Давайте проверим историю действий. Иногда сервис хранит удалённые файлы.\n\nМарк понял, что сейчас всё равно станет видно.\n\nОн смотрел на экран, где появлялись строки:\n\n«Удалено пользователем Mark…»\n\nДо того, как учитель успел прочитать, Марк сказал:\n\n— Это я.\n\nВсе повернулись.\n\n— Вчера. Я хотел удалить черновики и удалил папку. Потом испугался и написал, что сайт глючит.\n\nЛиза молчала.\n\n— Ты знал? — спросила она.\n\n— Да.\n\n— И смотрел, как я снова ищу фотографии?\n\nМарк опустил голову.\n\n— Да. Прости.\n\nЭто было гораздо неприятнее, чем признаться вчера.\n\nУчитель не стал спасать его фразой «ничего страшного».\n\n— Ошибка с папкой бывает. Но из-за того, что команда не знала правду, вы потеряли ещё время. Сейчас задача — восстановить, что можно, и решить, как Марк будет помогать исправлять остальное.\n\nВ истории действий действительно нашлась кнопка восстановления.\n\nБольшая часть фотографий вернулась.\n\nТри файла восстановить не удалось.\n\nМарк взял на себя поиск этих трёх фотографий и перепроверку подписей.\n\nЛиза всё ещё была сердита.\n\n— Я не могу сразу перестать злиться.\n\n— Понимаю.\n\n— Если в следующий раз что-то удалишь, скажи сразу.\n\n— Скажу.\n\n— Даже если я буду злиться.\n\n— Даже тогда.\n\nОни работали до вечера.\n\nНа конференции презентация открылась нормально.\n\nКогда Марк нажимал кнопку «следующий слайд», каждый раз немного боялся, что что-то снова исчезнет.\n\nНичего не исчезло.\n\nПосле выступления учитель попросил команду назвать один технический совет для будущих проектов.\n\nЮра сказал:\n\n— Делать копии.\n\nЛиза:\n\n— Не складывать всё в папку «временное».\n\nВсе засмеялись.\n\nМарк сказал:\n\n— И если удалил не то — сначала сказать, а потом уже чинить.\n\nЛиза посмотрела на него.\n\nНа этот раз тоже улыбнулась.\n\nПозже Марк создал в общей папке новый раздел.\n\nНазвал его не «ФИНАЛ_ТОЧНО_ФИНАЛ».\n\nА просто:\n\n«Резервная копия».\n\nИ поставил автоматическое сохранение.\n\nЧерез месяц Марк снова допустил ошибку в общей работе. На этот раз он случайно поставил неправильную дату на плакате.\n\nОн заметил это уже после печати.\n\nВнутри мгновенно появилось старое желание:\n\n«Может, никто не увидит».\n\nМарк посмотрел на плакат.\n\nПотом на команду.\n\n— Ребята, я дату перепутал. Нужно исправить.\n\nЛиза подняла брови.\n\n— Сразу сказал?\n\n— Сразу.\n\n— Прогресс.\n\nОни заклеили дату аккуратной наклейкой и напечатали правильную.\n\nНа всё ушло семь минут.\n\nМарк сравнил эти семь минут с тем вечером, когда он скрывал удалённую папку, а остальные заново искали фотографии.\n\nРазница была огромная.\n\nЕму всё равно было неприятно признавать ошибки. Иногда хотелось провалиться под стол.\n\nНо теперь он знал: стыд любит тишину и задержки.\n\nА исправление обычно начинается в тот момент, когда остальные наконец понимают, что случилось.","question":"Что больше всего мешает признаться в ошибке: страх наказания, чужая реакция, стыд или что-то другое?","image":"assets/images/stories/ischeznuvshaya-papka-dlinnaya.webp","audio":"","published":true},{"id":"7-9-09-korotkaya","topicId":"7-9-09","slug":"ischeznuvshaya-papka-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Стыдно признаться в ошибке","version":"Короткая","duration":"3–5 минут","title":"Исчезнувшая папка","hero":"Марк","teaser":"Марк случайно удаляет общую презентацию и пытается скрыть случившееся, но исправить ошибку удаётся только после того, как команда узнаёт правду.","text":"Команда Марка готовила презентацию к школьной конференции.\n\nВ общей папке лежали фотографии, карта и слайды.\n\nВечером Марк решил удалить старые черновики.\n\nОн нажал:\n\n«Удалить».\n\nИ случайно стёр папку почти со всеми фотографиями.\n\nМарк испугался.\n\nВместо «я удалил» он написал в общий чат:\n\n«Наверное, сайт глючит».\n\nНа следующий день Лиза снова искала фотографии, Юра скачивал файлы, а Марк молчал.\n\nУчитель предложил посмотреть историю действий.\n\nМарк понял, что там будет видно его имя.\n\n— Это я, — сказал он раньше. — Я случайно удалил папку. Потом испугался и соврал про сайт.\n\nЛиза рассердилась:\n\n— Ты знал, пока мы всё искали?\n\n— Да. Прости.\n\nУчитель помог найти функцию восстановления. Большая часть файлов вернулась.\n\nТри фотографии пропали совсем.\n\nМарк сам занялся их поиском и проверил все подписи.\n\nЛиза сказала:\n\n— Я всё ещё злюсь. Но в следующий раз скажи сразу.\n\n— Скажу.\n\nНа конференции всё сработало.\n\nПосле выступления Марк создал новую папку.\n\nНазвал её:\n\n«Резервная копия».\n\nИ включил автоматическое сохранение.\n\nПозже Марк перепутал дату на уже напечатанном плакате.\n\nПервой мыслью было:\n\n«Может, никто не заметит».\n\nНо он сразу сказал:\n\n— Я ошибся в дате. Нужно исправить.\n\n— Сразу сказал? — удивилась Лиза.\n\nОни заклеили неправильную дату и напечатали новую.\n\nНа всё ушло семь минут.\n\nМарк всё ещё не любил признаваться в ошибках.\n\nНо семь минут оказались гораздо легче целого дня молчания.","question":"Что больше всего мешает признаться в ошибке: страх наказания, чужая реакция, стыд или что-то другое?","image":"assets/images/stories/ischeznuvshaya-papka-korotkaya.webp","audio":"","published":true},{"id":"7-9-10-dlinnaya","topicId":"7-9-10","slug":"bashnya-bez-vershiny-dlinnaya","age":"7–9 лет","ageKey":"7-9","theme":"Хочу быть первым","version":"Длинная","duration":"10–15 минут","title":"Башня без вершины","hero":"Элина","teaser":"Элина мчится по головоломкам башни быстрее всех, но последняя дверь открывается только там, где скорость перестаёт быть единственным преимуществом.","text":"В городском парке на один день построили Башню задач.\n\nЭто был высокий деревянный лабиринт с лестницами, дверцами, кодами и маленькими флажками.\n\nПравило звучало просто:\n\n— Пройдите семь этажей и доберитесь до верхней площадки.\n\nЭлина услышала только одну часть:\n\n«Кто быстрее».\n\nОна любила быть первой.\n\nПервая закончила — приятно.\n\nПервая добежала — приятно.\n\nПервая подняла руку — тоже приятно.\n\nВ Башню она вошла почти бегом.\n\nНа первом этаже нужно было собрать пазл из четырёх частей.\n\nЩёлк-щёлк.\n\nГотово.\n\nЭлина первой открыла дверь.\n\nНа втором — найти число в ряду.\n\nОна решила мгновенно.\n\nНа третьем — пройти по цветным плиткам, не наступая на красные.\n\nЭлина прыгала так быстро, что обогнала ещё двух ребят.\n\n— Я первая! — крикнула она лестнице.\n\nНа четвёртом этаже стояла большая коробка с прорезями. Нужно было на ощупь определить предмет.\n\nЭлина сунула руку.\n\n— Ключ!\n\nНеправильно.\n\n— Ложка!\n\nНеправильно.\n\nОна слышала, как сзади приближаются другие.\n\nСердце застучало быстрее.\n\n«Сейчас обгонят».\n\nЭлина начала называть всё подряд.\n\n— Расчёска! Карандаш! Вилка!\n\n— Можно потрогать медленнее, — сказал ведущий.\n\nЭлина остановилась.\n\nПальцами почувствовала круглую ручку и мягкие щетинки.\n\n— Кисточка.\n\nДверь открылась.\n\nОна побежала дальше.\n\nНа пятом этаже был текст с загадкой.\n\nЭлина прочитала только первую строчку и сразу нажала кнопку ответа.\n\nКрасный свет.\n\nНеверно.\n\nОна нажала другой.\n\nСнова красный.\n\nЗа спиной появился мальчик Артур.\n\nОн прочитал загадку до конца.\n\n— Ответ «эхо».\n\nЗелёный свет.\n\nДверь открылась для обоих.\n\nЭлина выскочила первой.\n\n«Теперь нельзя останавливаться».\n\nНа шестом этаже нужно было перенести три шарика по наклонному желобу. Элина гнала их слишком быстро, и два вылетели.\n\nАртур шёл медленнее и закончил раньше.\n\nТеперь он был впереди.\n\nЭлина почувствовала знакомую горячую злость.\n\nОна почти не замечала саму Башню.\n\nТолько спину Артура.\n\nНа седьмом этаже они оказались одновременно.\n\nПеред ними была круглая комната и четыре большие напольные кнопки по углам.\n\nНа двери написано:\n\n«Откроется, когда загорятся все четыре».\n\nЭлина наступила на одну.\n\nЗагорелась первая лампа.\n\nОна перебежала на вторую.\n\nПервая погасла.\n\n— Нужно что-то положить, — сказала Элина.\n\nОни попробовали рюкзаки. Кнопкам не хватало веса.\n\nК этому моменту подошли ещё две девочки.\n\n— Вставайте сюда! — крикнул Артур.\n\nКаждый занял кнопку.\n\nЧетыре лампы загорелись.\n\nЩёлк.\n\nДверь открылась.\n\nВсе четверо бросились к лестнице на верхнюю площадку.\n\nЭлина рванула быстрее.\n\nА потом остановилась на первой ступеньке.\n\n— Если мы уйдём, кнопки погаснут.\n\nТочно.\n\nДверь начала закрываться.\n\n— Нужны ещё люди, — сказала одна девочка.\n\nОни подождали следующую группу. Объяснили, как работает комната. Когда новые участники встали на кнопки, первая четвёрка смогла подняться.\n\nНа верхней площадке не было финишной ленты.\n\nНе было пьедестала.\n\nСтоял только большой колокол.\n\nПод ним табличка:\n\n«Позвони, если дошёл. Передай дорогу следующему».\n\nЭлина посмотрела на Артура.\n\n— Так кто первый?\n\nОн пожал плечами.\n\n— Мы вроде вместе открыли дверь.\n\nЭлина даже немного разочаровалась.\n\nПотом ударила в колокол.\n\nБом-м-м!\n\nСнизу раздались радостные крики.\n\nОна наклонилась через перила и увидела следующую группу у шестого этажа.\n\n— На седьмом нужны четыре человека! — крикнула Элина.\n\nПосле Башни организаторы всё-таки выдали результаты.\n\nУ каждого было время прохождения отдельных этажей.\n\nЭлина оказалась самой быстрой на первом, втором и третьем.\n\nОна очень обрадовалась.\n\nАртур был быстрее на шестом.\n\nА общее время у них оказалось одинаковым — потому что последнюю дверь они открывали вместе.\n\n— Я всё равно хочу в следующий раз пройти быстрее, — сказала Элина.\n\n— Я тоже, — ответил Артур.\n\n— Но загадку я сначала дочитаю.\n\nНа обратном пути Элина думала о странной Башне.\n\nУ неё действительно была вершина — площадка с колоколом.\n\nНо добраться до неё «первой в одиночку» оказалось невозможно.\n\nИ почему-то от этого приключение стало не меньше похоже на соревнование.\n\nПросто в нём оказалось больше одного способа победить.\n\nЧерез месяц Элина участвовала в обычной школьной эстафете.\n\nТам всё было проще: одна дистанция, один финиш, одно время.\n\nОна бежала изо всех сил.\n\nИ пришла первой.\n\nЭлина радовалась совершенно открыто:\n\n— Да!\n\nАртур, который оказался третьим, дал ей пять.\n\n— На этот раз никаких четырёх кнопок.\n\n— И никаких загадок, — засмеялась Элина.\n\nЕй понравилось заметить: желание быть первой никуда не исчезло и не должно было исчезать.\n\nПросто теперь она различала ситуации.\n\nГде-то есть настоящий финиш и можно честно стараться прибежать раньше.\n\nГде-то важнее точность.\n\nГде-то без других людей дверь вообще не откроется.\n\nА иногда первое место сегодня не гарантирует первое место завтра.\n\nНа полке у Элины стояла медаль за эстафету и бумажный значок из Башни задач с маленьким колоколом.\n\nОна любила оба.\n\nОдин напоминал, как здорово мчаться к финишу.\n\nДругой — что иногда вершина начинается с четырёх кнопок, на которые нужно встать вместе.","question":"Когда тебе особенно приятно быть первым, а когда важнее что-то другое?","image":"assets/images/stories/bashnya-bez-vershiny-dlinnaya.webp","audio":"","published":true},{"id":"7-9-10-korotkaya","topicId":"7-9-10","slug":"bashnya-bez-vershiny-korotkaya","age":"7–9 лет","ageKey":"7-9","theme":"Хочу быть первым","version":"Короткая","duration":"3–5 минут","title":"Башня без вершины","hero":"Элина","teaser":"Элина мчится по головоломкам башни быстрее всех, но последняя дверь открывается только там, где скорость перестаёт быть единственным преимуществом.","text":"В парке построили Башню задач.\n\nЭлина очень хотела пройти её первой.\n\nПазл — готово.\n\nЧисловой ряд — готово.\n\nЦветные плитки — быстро.\n\nНа четвёртом этаже нужно было узнать предмет на ощупь.\n\nЭлина торопилась:\n\n— Ключ! Ложка! Вилка!\n\nНичего не подходило.\n\nОна заставила себя потрогать медленнее.\n\n— Кисточка.\n\nДверь открылась.\n\nНа следующем этаже Элина не дочитала загадку и дважды ошиблась. Мальчик Артур прочитал её до конца и прошёл вперёд.\n\nЭлина побежала догонять.\n\nНа последнем этаже были четыре напольные кнопки.\n\nЧтобы открыть дверь, нужно было нажать все сразу.\n\nЭлина встала на одну.\n\nАртур — на вторую.\n\nПодошли ещё две девочки.\n\nЧетыре лампы загорелись.\n\nЩёлк!\n\nДверь открылась.\n\nНо стоило кому-то уйти с кнопки, она начинала закрываться.\n\nПришлось дождаться следующей группы и передать им свои места.\n\nНа верхней площадке не было пьедестала.\n\nТолько колокол.\n\nБом-м-м!\n\nПозже оказалось, что Элина была самой быстрой на первых трёх этажах.\n\nОна очень обрадовалась.\n\n— В следующий раз хочу ещё быстрее, — сказала она Артуру.\n\nПотом добавила:\n\n— Но загадку сначала дочитаю.\n\nПозже Элина участвовала в обычной эстафете и пришла первой.\n\n— Да! — закричала она.\n\nЕй по-прежнему очень нравилось побеждать.\n\nНо теперь она лучше различала игры.\n\nГде-то есть настоящий финиш и можно стараться прибежать раньше всех.\n\nГде-то важнее точность.\n\nА где-то дверь вообще не открывается без других людей.\n\nНа полке Элины стояли рядом медаль за эстафету и значок из Башни задач.\n\nОна любила оба.","question":"Когда тебе особенно приятно быть первым, а когда важнее что-то другое?","image":"assets/images/stories/bashnya-bez-vershiny-korotkaya.webp","audio":"","published":true}];
